import {Container,Table,Spinner,Button} from 'react-bootstrap';
import {useEffect,useState} from 'react';
import axios from 'axios';
import jsPDF from 'jspdf'; 
import 'jspdf-autotable';

function convertDate(inputFormat) {
  function pad(s) { return (s < 10) ? '0' + s : s; }
  var d = new Date(inputFormat)
  return [pad(d.getDate()), pad(d.getMonth()+1), d.getFullYear()].join('/')
}

function generate(temp,user) {  

  const unit = "pt";
  const size = "A4"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);
  doc.setFont(undefined, 'bold')

  doc.setFontSize(15);

  const title = `Activity Report for User: ${user}`;
  const headers = [["S No.", "Tank BA No.","Info","Completed","Reason","TimeStamp"]];

  const data = temp.map((elem,index)=> {
    let completed = "";
    let item = "";
    let reason = ""
    try{item = elem.info.split('of truck')[0].split('item:')[1]}catch(e){}
    try {completed= "Completed" + elem.info.split('completed')[1].split('by:')[0]}catch(e){}
    try{reason = elem.info.split("reason :")[1].split("'")[0]}catch(e){}

    if (reason === " None") {
      reason = "";
    }
    if (completed === "Completed removed ") {
      completed = "";
    }
    
    return [index+1, elem.truck,item,completed,reason,convertDate(elem.timestamp.split(',')[0])];
  });

  let content = {
    startY: 50,
    head: headers,
    body: data,
    theme : "grid",
    styles : {
      halign : "left",
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    },
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
    
  };

  doc.text(title, marginLeft, 40);
  doc.autoTable(content);
  doc.save("report.pdf")
}  

const UserActivityDetails = (props)=>{
    const [data,setData] = useState(null)

    useEffect(()=>{

            var data = JSON.stringify({"username":props.id,
          "type": localStorage.getItem('vehicletype')});


    var config = {
    method: 'post',
    url: 'http://localhost:8000/api/activityhistory',
    headers: { 
        'Content-Type': 'application/json'
    },
    data : data
    };

    axios(config)
    .then(function (response) {
        setData(response.data)

    })
    .catch(function (error) {
    console.log(error);
    });
// eslint-disable-next-line
    },[])


    return (
        <>
        <Container>
        {data !== null? (
            <>
            <Table striped bordered hover variant="dark">
  <thead>
    <tr>
      <th>S No. </th>
      <th>Tank BA No.</th>
      <th>User</th>
      <th>Info</th>
      <th>Completed</th>
      <th>Reason</th>
      <th>Time Stamp</th>
    </tr>
  </thead>
  <tbody>
  {data.map((elem,index)=>{
    let completed = "";
    let item = "";
    let reason=""
    try{item = elem.info.split('of truck')[0].split('item:')[1]}catch(e){}
    try {completed= "Completed" + elem.info.split('completed')[1].split('by:')[0]}catch(e){}
    try{reason = elem.info.split("reason :")[1].split("'")[0]}catch(e){}
    console.log(completed)

      return (
        <tr>
      <td>{index + 1}</td>
      <td>{elem.truck}</td>
      <td>{props.name}</td>
      <td>{item}</td>
      <td>{completed === "Completed removed "?"":completed}</td>
      <td>{reason === " None"?"":reason}</td>
      <td>{convertDate(elem.timestamp.split(',')[0])}</td>
    </tr>
      )
  })}
    
    
  </tbody>
</Table>
            </>
        ): (
            <>
            <Spinner animation="border" role="status">
                <span className="visually-hidden">Loading...</span>
                </Spinner>
               </>
        )}
          
          <Button variant="success" onClick={()=>{
            generate(data,props.name)
          }}>Generate Report</Button>
        </Container>
        </>
    )
}

export default UserActivityDetails;