import {Modal,Button,Table} from 'react-bootstrap';
import {useState,useEffect} from 'react';
import axios from 'axios';

function find_difference(firstDate,secondDate){
  const oneDay = 24 * 60 * 60 * 1000; 
  const diffDays = Math.round((firstDate - secondDate) / oneDay);
  return diffDays
}

const TruckNotification = ()=>{

  const [data,setData] = useState(null)
  const [show,setShow] = useState(true);

      useEffect(()=>{
        var config = {
          method: 'get',
          url: 'http://localhost:8000/api/trucklist',
          headers: { 
            'Content-Type': 'application/json'
          },
        };
        
        axios(config)
        .then(function (response) {
            setData(response.data)
           
          
        })
        .catch(function (error) {
          console.log(error);
        });
      },[])

    const handleClose= ()=>setShow(false)
    


  
    
    return (
        <>
        <Modal show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>Tank Notification</Modal.Title>
        </Modal.Header>
        <Modal.Body>
        {data !== null ? (
          <Table striped bordered hover variant="dark">
  <thead>
    <tr>
      <th> S No. </th>
      <th>Tank BA No.</th>
      <th>ETA/late</th>
    </tr>
  </thead>
  <tbody>
  {data.filter((elem)=>{
    let today = new Date()
      let depart = new Date(Date.parse(elem.estimatedepart))
      today.setHours(0, 0, 0);   
      depart.setHours(0,0,0)
      if(today > depart)
      {elem.status = "Late"; return true;}
      else if(find_difference(today,depart) === 1)
      {elem.status = "1 Day Left"; return true; }
      else if(find_difference(today,depart) === 2)
      {elem.status = "2 Days Left"; return true; }
      else if(find_difference(today,depart) === 3)
      {elem.status = "3 Days Left"; return true; }
      else if(find_difference(today,depart) === 4)
      {elem.status = "4 Days Left"; return true; }
      else if(find_difference(today,depart) === 5)
      {elem.status = "5 Days Left"; return true; } 
      else if(find_difference(today,depart) >= 5){
        elem.status = "Late"; return true;
      }

      return false;
  }).map((elem,index)=>{
    return (
      <tr>
      <td>{index + 1}</td>
      <td>{elem.reg}</td>
      <td>{elem.status}</td>
    </tr>
    )
  })}
    
  
  </tbody>
</Table>
        ):null}
        


        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleClose}>
            Close
          </Button>
        
        </Modal.Footer>
      </Modal>
        </>
    )
}

export default TruckNotification;