import jsPDF from 'jspdf'; 
import 'jspdf-autotable';


function generate_report(temp, tank){
  const unit = "pt";
  const size = "A4"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);

  doc.setFontSize(15);

  const title = `DELAY REPORT TANK BA NO. : ${tank}`;
  const headers = [["S No.", "Causes","Delay (No. of Days)","Addl Activity to Counteract Delay","Delay Reduced By (In No. of Days)","Remarks"]];
  const data = temp.data.map((elem,index)=> {
    return [index+1, elem.item,elem.delay,elem.addl_activity,elem.delay_reduction,elem.remarks];
  
  });
  data.push(["","No. of Days",temp.delay_total,"",temp.delay_redction,""])

  let content = {
    startY: 50,
    head: headers,
    body: data,
    theme : "grid",
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    }
 
  };

  doc.text(title, marginLeft, 40);
  doc.autoTable(content);
  doc.setLineWidth(2);
  doc.autoTable({
    head: [[`Net Delay (in Days) : ${temp.delay}`]],
});  

  doc.save("report.pdf")

}

