import {Button,Modal,Form} from 'react-bootstrap'; 
import axios from 'axios';
import {useState} from 'react';
window.reg =null 
window.unit = null
window.type = null
window.reportingdate = null
window.remarks=null


const AddYearTargetTrucks = (props)=>{
    const [miss,setMiss] = useState(false);
    const [exists, setExists] = useState(false)
    const handleClose = () => props.module(false);
    return (
        <>

        <Modal show={props.show} onHide={handleClose}>
          <Modal.Header closeButton>
            <Modal.Title><p className="fw-bold">Add A Target Tank</p></Modal.Title>
          </Modal.Header>
          <Modal.Body>
          {miss?(<p className="text-center" style={{color:"red"}}>Missing Values</p>):null}
          {exists?(<p className="text-center" style={{color:"red"}}>Tank Already Exists</p>):null}
                <Form>
        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Tank BA Number</Form.Label>
            <Form.Control onChange={(e)=>window.reg=e.target.value} type="text" placeholder="For Eg: T54321234" />
        </Form.Group>

        <Form.Group controlId="gender" className="my-2">
            <Form.Label>Vehicle Type</Form.Label>
            <Form.Control as="select" onChange={(e)=>{window.type=e.target.value}}>
              <option>Select a Vehicle type</option>
              <option value={"T90"}>T90</option>
              <option value={"T72"}>T72</option>
              <option value={"BMP"}>BMP</option>
            </Form.Control>
          </Form.Group>

        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Unit</Form.Label>
            <Form.Control onChange={(e)=>window.unit=e.target.value} type="text"  />
        </Form.Group>
        
        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Arrival Date</Form.Label>
            <Form.Control onChange={(e)=>window.reportingdate=e.target.value} type="date"  />
        </Form.Group>

        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Remarks</Form.Label>
            <Form.Control onChange={(e)=>window.remarks=e.target.value} type="text"  />
        </Form.Group>
       </Form>

        
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={handleClose}>
              Close
            </Button>
            <Button type="submit" variant="primary" onClick={()=>{

            
            if(window.reg!== null && window.unit !== null && window.type!==null){
            //   if(props.list.includes(window.reg) === true){
            //     setExists(true)
            //   }
            //   else{
            //     props.loadmodule(true)
      

              var data = JSON.stringify({
              "regno":window.reg,
              "type" : window.type,
              "unit" : window.unit,
              "arrival" : window.reportingdate,
              "remarks" : window.remarks,
              });
          
          var config = {
            method: 'post',
            url: 'http://localhost:8000/api/updatetargetrucks',
            headers: { 
              'Content-Type': 'application/json'
            },
            data : data
          };

          axios(config)
          .then(function (response) {
            handleClose()
            setMiss(false)
            props.loadmodule(false)

          })
          .catch(function (error) {
            console.log(error);
          });
              
        // }
            }else {
              setMiss(true)
              
            }
              }}>
            Submit 
            </Button>
          </Modal.Footer>
        </Modal>
      </>
    )
}




export default AddYearTargetTrucks;