import {Container,Table,Spinner,Button} from 'react-bootstrap';
import {useEffect,useState} from 'react';
import axios from 'axios';
import jsPDF from 'jspdf'; 
import 'jspdf-autotable';

function formatDate(date) {
  
  var d = new Date(date),
      month = '' + (d.getMonth() + 1),
      day = '' + d.getDate(),
      year = d.getFullYear();

  if (month.length < 2) 
      month = '0' + month;
  if (day.length < 2) 
      day = '0' + day;

  return [day, month, year].join('-');
}

function generate(temp,user) {  

  const unit = "pt";
  const size = "A4"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);
  doc.setFont(undefined, 'bold')

  doc.setFontSize(15);

  const title = `Rotables Report for User : ${user}`;
  const headers = [["S No.", "Tank BA No.","Item","Date Out","Date In","Eqpt Status","Fitted By","Working Days","Time Stamp"]];

  const data = temp.map((elem,index)=> {
    let datein="",dateout="",eqptstatus="",workingdays="",fittedby = ""
    try{
        if(elem.info.split('datein to:')[1].split(',')[0].trim()==="None"){
        datein="  -"
        } 
        else{
          datein=new Date(elem.info.split('datein to:')[1].split(',')[0].trim())
          datein.setDate(datein.getDate()-1);
          datein = formatDate(datein);      
  }}catch(e){}
    try{
          if(elem.info.split('dateout to:')[1].split(',')[0].trim()==="None"){
          dateout="   -"
  } 
          else{
            dateout=new Date(elem.info.split('dateout to:')[1].split(',')[0].trim())
            dateout.setDate(dateout.getDate()-1);
            dateout = formatDate(dateout);      
  }}catch(e){}
    try{eqptstatus=elem.info.split('eqptstatus to:')[1].split(',')[0]}catch(e){}
    try{workingdays=elem.info.split('workingdays to:')[1].split(',')[0]}catch(e){}
    try{fittedby = elem.info.split('fittedby to:')[1].split(',')[0]}catch(e){}
    if(datein === "None") datein = "-"
    if(dateout === "None") dateout = "-"
    return [index+1, elem.truck,elem.item,datein,dateout,eqptstatus,fittedby,workingdays,
      elem.timestamp.split(',')[0]]
  
  });

  let content = {
    startY: 50,
    head: headers,
    body: data,
    theme : "grid",
    styles : {
      halign : "left",
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    },
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
  };

  doc.text(title, marginLeft, 40);
  doc.autoTable(content);
  doc.save("report.pdf")
}  



const UserRotablesReport = (props)=>{
    const [data,setData] = useState(null)

    useEffect(()=>{

        var data = JSON.stringify({"username":props.id,
      "type":localStorage.getItem('vehicletype')});

        var config = {
          method: 'post',
          url: 'http://localhost:8000/api/truckrotablehistory',
          headers: { 
            'Content-Type': 'application/json'
          },
          data : data
        };
        
        axios(config)
        .then(function (response) {
            setData(response.data)
        })
        .catch(function (error) {
          console.log(error);
        });
        
        // eslint-disable-next-line
    },[])


    return (
        <>
        <Container>
        {data !== null? (
            <>
            <Table striped bordered hover variant="dark">
  <thead>
    <tr>
      <th>S No. </th>
      <th>Tank BA No.</th>
      <th>Username</th>
      <th>Item</th>
      <th className='col-1'>Date Out</th>
      <th className='col-1'>Date In</th>
      <th>Eqpt Status</th>
      <th>Fitted By</th>
      <th>Working Days</th>
      <th>Time Stamp</th>
    </tr>
  </thead>
  <tbody>
  {data.map((elem,index)=>{
    let datein="",dateout="",eqptstatus="",workingdays="",fittedby = ""
    try{
        if(elem.info.split('datein to:')[1].split(',')[0].trim()==="None"){
            datein="  -"
        } 
        else{
          datein=new Date(elem.info.split('datein to:')[1].split(',')[0].trim())
          datein.setDate(datein.getDate()-1);
          datein = formatDate(datein);      
        }
  }catch(e){}
    try{if(elem.info.split('dateout to:')[1].split(',')[0].trim()==="None"){
      dateout="   -"
  } 
  else{
    dateout=new Date(elem.info.split('dateout to:')[1].split(',')[0].trim())
    dateout.setDate(dateout.getDate()-1);
    dateout = formatDate(dateout);      
  }
  }catch(e){}
    try{eqptstatus=elem.info.split('eqptstatus to:')[1].split(',')[0]}catch(e){}
    try{workingdays=elem.info.split('workingdays to:')[1].split(',')[0]}catch(e){}
    try{fittedby = elem.info.split('fittedby to:')[1].split(',')[0]}catch(e){}
    if(datein === "None") datein = ""
    if(dateout === "None") dateout = "" 
    
    return (
        <tr>
      <td>{index + 1}</td>
      <td>{elem.truck}</td>
      <td>{props.name}</td>
      <td>{elem.item}</td>
      <td style={{}}>{dateout}</td>
      <td style={{}}>{datein}</td>
      <td>{eqptstatus}</td>
      <td>{fittedby}</td>
      <td>{workingdays}</td>
      <td>{elem.timestamp.split(',')[0]}</td>
    </tr>
      )
  })}
    
    
  </tbody>
</Table>
            </>
        ): (
            <>
            <Spinner animation="border" role="status">
                <span className="visually-hidden">Loading...</span>
                </Spinner>
               </>
        )}
        <Button variant="success" onClick={()=>{
            generate(data,props.name)
          }}>Generate Report</Button>
        </Container>
        </>
    )
}

export default UserRotablesReport;