import {Container,Table,Button,Spinner} from 'react-bootstrap';
import {useEffect,useState} from 'react';
import axios from 'axios';
import jsPDF from 'jspdf';
import 'jspdf-autotable';

function convertDate(inputFormat) {
  function pad(s) { return (s < 10) ? '0' + s : s; }
  var d = new Date(inputFormat)
  return [pad(d.getDate()), pad(d.getMonth()+1), d.getFullYear()].join('/')
}

function generate(temp,tank) {  

    const unit = "pt";
    const size = "A4"; // Use A1, A2, A3 or A4
    const orientation = "portrait"; // portrait or landscape
  
    const marginLeft = 40;
    const doc = new jsPDF(orientation, unit, size);
    doc.setFont(undefined, 'bold')

    doc.setFontSize(15);
  
    const title = `Expendable Item Report for Tank BA No : ${tank}`;
    const headers = [["S No","Username","Part Number","Item","AU","Auth for 01 Tks","Fitted (Yes/No)?","Issued from Ord","Issued from LP","Time Stamp"]];

    
    const data = temp.map((elem,index)=> {
      let fitted = "",partnumber = "",issuedfromexord="",issuedfromlp=""
      try{fitted=elem.info.split('fitted')[1].split(',')[0]}catch(e){}
      try{partnumber=partnumber=elem.info.split('for')[1].split(',')[0]}catch(e){}
      try{issuedfromexord=elem.info.split('issuedfromexord: ')[1].split(', issuedfromlp')[0]}catch(e){}
      try{issuedfromlp=elem.info.split('issuedfromlp')[1].split(':')[1].split(',')[0]}catch(e){}
      fitted = (fitted==" yes" || fitted==" Yes")?"Yes":"No"
      return [index+1, elem.user,partnumber,elem.item,elem.au, elem.auth01tks,fitted,
        issuedfromexord,
        issuedfromlp,
        convertDate(elem.timestamp.split(',')[0])]

    });
    let totalOrd = 0;
  let totalLp = 0;
  let totalYesCount = 0;
  let totalNoCount = 0;

  data.forEach((elem)=>{
    if(elem[6] === "Yes") {
      totalYesCount++;
      if (elem[7]) {
        totalOrd++;
      }
      if (elem[8]) {
        totalLp++;
      }
    }
    else{
      totalNoCount++;
    }
    
  })
    let content = {
      startY: 50,
      head: headers,
      body: data,
      theme : "grid",
      styles : {
        halign : "left",
      },
      bodyStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center',
      },
      headStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center'
      },
    };
  
    doc.text(title,doc.internal.pageSize.getWidth() / 2, 20, { align: "center" });
    doc.autoTable(content);
    doc.autoTable({
      head: [["Yes","No","Total Issued from Ord", "Total Issued from LP"]],
      body: [[totalYesCount,totalNoCount,totalOrd,totalLp]],
      headStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center'
      },
      bodyStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center',
        fontStyle: 'bold'
      },
      columnStyles: {
        0: {cellWidth: 70},
        1: {cellWidth: 70},
        2: {cellWidth: 200},
        3: {cellWidth: 200},
        
      }
  });
    doc.save("inventoryreport.pdf")
  }  
  

const ExpendablesReport = (props)=>{

    const [data,setData] = useState(null)

    useEffect(()=>{
        var config = {
        method: 'get',
        url: `http://localhost:8000/api/expendableitemhistory/${props.reg}`,
        headers: { 
            'Content-Type': 'application/json'
        },
        };

        axios(config)
        .then(function (response) {
            setData(response.data)
            })
        .catch(function (error) {
        console.log(error);
        });
// eslint-disable-next-line
    },[])



    return (
        <>


        <Container className="mx-6 my-5">
        <h3 className="fw-bold"> Expendables Report</h3>

    
        {data !== null? (
            <Table responsive striped bordered hover variant="dark">
  <thead>
    <tr>
    <th>S No </th>
      <th>Username</th>
      <th>Part Number</th>
      <th>Item</th>
      <th>AU</th>
      <th>Auth for 01 Tks</th>
      <th>Fitted (Yes/No)</th>
      <th>Issued From Ord</th>
      <th>Issued From LP</th>
      <th>Time Stamp</th>
    </tr>
  </thead>
  <tbody>
 {
     data.map((elem,index)=>{

      let fitted = "",partnumber = "",issuedfromexord="",issuedfromlp=""
      try{fitted=elem.info.split('fitted')[1].split(',')[0]    }catch(e){}
      try{partnumber=elem.info.split('for')[1].split(',')[0]}catch(e){}
      try{issuedfromexord=elem.info.split('issuedfromexord: ')[1].split(', issuedfromlp')[0]}catch(e){}
      try{issuedfromlp=elem.info.split('issuedfromlp')[1].split(':')[1].split(',')[0]}catch(e){}
      fitted = (fitted==" yes" || fitted==" Yes")?"Yes":"No"
      return (
          <tr>
          <td>{index + 1}</td>
          <td>{elem.user}</td>
          <td>{partnumber}</td>
          <td>{elem.item}</td>
          <td>{elem.au}</td>
          <td>{elem.auth01tks}</td>
          <td>{fitted}</td>
          <td>{issuedfromexord}</td>
          <td>{issuedfromlp}</td>
          <td>{convertDate(elem.timestamp.split(',')[0])}</td>
        </tr>
         )
     })
 }  
  </tbody>
</Table>
        ) : (
            <Container>
            <Spinner animation="border" role="status">
    <span className="visually-hidden">Loading...</span>
    </Spinner>
            </Container>
        )}
        <Button onClick={()=>{
            generate(data,props.reg)
        }}   className="mb-2 ">Click to Generate Report</Button>
        </Container>
        </>
    )
}


export default ExpendablesReport;