import {Button,Modal,Table,Form} from 'react-bootstrap'; 
import jsPDF from 'jspdf';
import 'jspdf-autotable';

function convertDate(inputFormat) {
    if(inputFormat==null){
        return('');
    }
    function pad(s) { return (s < 10) ? '0' + s : s; }
    var d = new Date(inputFormat)
    return [pad(d.getDate()), pad(d.getMonth()+1), d.getFullYear()].join('/')
  }
function generate(temp, variant,variants,dateOptions) {  

    const unit = "pt";
    const size = "A3"; // Use A1, A2, A3 or A4
    const orientation = "portrait"; // portrait or landscape
  
    const marginLeft = 250;
    const doc = new jsPDF(orientation, unit, size);
    doc.setFont(undefined, 'bold')

    doc.setFontSize(15);

    const title = `${variants[variant]}`;
    const headers = [["S No","Eqpt Type","Tank BA No","Unit","Date In",`${dateOptions[variant]}`]];

    const data =  temp.filter((elem)=>{
        return elem;
      }).sort(function(a,b){
        let a1 = 10000000000, b1 = 10000000000;
        if(a.target !== null) a1 = a.target;
        if(b.target !== null) b1 = b.target;
        return a1 - b1;
     }).map((elem,index)=>{
        let tempvar = variant;
        let actualWcnDate = "", collectionDate="", estimatedepart="",estimatedepart1="";
        // to find bayout date or departure date of table 1
        if(tempvar==1){
            if(elem.vehType=="BMP-I/II"){
                estimatedepart = new Date(elem.arrival);
                estimatedepart.setDate(estimatedepart.getDate() + 42);
                estimatedepart=convertDate(estimatedepart);
                // console.log(estimatedepart)
            }
            if(elem.vehType=="T-90"){
                estimatedepart = new Date(elem.arrival);
                estimatedepart.setDate(estimatedepart.getDate() + 51);
                estimatedepart=convertDate(estimatedepart);
                // console.log(estimatedepart)
            }
            if(elem.vehType=="T-72"){
                estimatedepart = new Date(elem.arrival);
                estimatedepart.setDate(estimatedepart.getDate() + 52);
                estimatedepart=convertDate(estimatedepart);
                // console.log(estimatedepart)
            }
        }
        if(tempvar==2){

            if(elem.vehType=="BMP-I/II"){
                estimatedepart1 = new Date(elem.arrival);
                estimatedepart1.setDate(estimatedepart1.getDate() + 68);
                estimatedepart1=convertDate(estimatedepart1);
                // console.log(estimatedepart1)
            }
            if(elem.vehType=="T-90"){
                estimatedepart1 = new Date(elem.arrival);
                estimatedepart1.setDate(estimatedepart1.getDate() + 76);
                estimatedepart1=convertDate(estimatedepart1);
                // console.log(estimatedepart1)
            }
            if(elem.vehType=="T-72"){
                estimatedepart1 = new Date(elem.arrival);
                estimatedepart1.setDate(estimatedepart1.getDate() + 74);
                estimatedepart1=convertDate(estimatedepart1);
                // console.log(estimatedepart1)
            }
        }
        if(elem.actual_wcn_date==null)actualWcnDate="";
        else
            actualWcnDate=convertDate(elem.actual_wcn_date.split(',')[0]);
        
        if(elem.collection_date==null)collectionDate="";
        else
            collectionDate=convertDate(elem.collection_date.split(',')[0]);
        
        return(

            [
                (tempvar==1)?(elem.target):index+1,
                elem.vehType,
                elem.reg,
                elem.unit,
                convertDate(elem.arrival.split(',')[0]),
                (tempvar==1)?(estimatedepart):(tempvar==2)?(estimatedepart1):(tempvar==3)?(actualWcnDate):(collectionDate)
            ]
            )
            
            
    });
    // console.log("hello");
    // console.log(data)
    let content = {
        startY: 50,
        margin : {left : 60},
        head: headers,
        body: data,
        theme : "grid",
        styles : {
          halign : "left",
        },
        bodyStyles: {
          lineWidth: 1,
          lineColor: 10,
          valign: "middle",
          halign: 'center'
        },
        headStyles: {
          lineWidth: 1,
          lineColor: 10,
          valign: "middle",
          halign: 'center'
        },
        columnStyles: {
        0: {cellWidth: 120},
        1: {cellWidth: 120},
        2: {cellWidth: 120},
        3: {cellWidth: 120},
        4: {cellWidth: 120},
        5: {cellWidth: 120},
        }
        
      };
    doc.text(title, doc.internal.pageSize.getWidth()/2, 30, { align: "center" });
    doc.autoTable(content);
    doc.save("inventoryreport.pdf")
}
