import { Container,Form,Button,Alert} from "react-bootstrap"
import {Link,useHistory} from 'react-router-dom';
import axios from 'axios';
import {useState} from 'react';
let username=""
let password=""

const LoginPage = ()=>{

  const [show,setShow] = useState(false)
  const history = useHistory()
  localStorage.setItem('navtype','nav1');
    return (
        <>
        {show?(
        <Alert variant="danger">
          Please Check whether you have typed everything correctly
      </Alert>
        ):null}
        
        <Container className="my-5 bg-dark text-light py-4 rounded" style={{width:'80%'}}>
            <h2 className="fw-bold text-center">Welcome to MR Process Management System</h2>


    <Form className="mx-5 my-5" >
  <Form.Group  className="my-3" controlId="formBasicEmail">
    <Form.Label>User Id (for A Veh Driver)</Form.Label>
    <Form.Control onChange={(e)=>username=e.target.value} type="text" placeholder="Enter User Id" />
  </Form.Group>

  <Form.Group className="mb-3" controlId="formBasicPassword">
    <Form.Label>Password</Form.Label>
    <Form.Control onChange={(e)=>password=e.target.value} className="col-4" type="password" placeholder="Enter Password" />
  </Form.Group>
 <Button type="submit" size="md" variant="primary" 
 onClick={()=>{
  localStorage.removeItem('id')
  localStorage.removeItem('permission')
  if(username=== "" || password === "")
        setShow(true)
        else
        {
          var data = JSON.stringify({"username":username,"password":password});
          var config = {
            method: 'post',
            url: 'http://localhost:8000/api/login',
            headers: { 
              'Content-Type': 'application/json'
            },
            data : data
          };
          axios(config)
          .then(function (response) {
            var res_data = response.data;
            if(res_data.message=== "valid")
              {         
                console.log(localStorage)
                localStorage.setItem("id",btoa(res_data.username))
                localStorage.setItem("name",btoa(res_data.name))
                localStorage.setItem("permission",btoa(res_data.permission))
                if(localStorage.getItem('vehicletype') === null)
                localStorage.setItem('vehicletype','T90')
                history.push('/vehicleselection')
                window.location.reload()
                

              }
              else
              setShow(true)
          })
          .catch(function (error) {
            setShow(true)
          });
        }
  }}>
    Submit
  </Button>
  <p className="fw-bold mx-2" style={{display:'inline'}}>{'  Or  '}</p>
<Link to="/register"><Button size="md" variant="danger">
    Register Yourself
  </Button> </Link>
  </Form>
  
        </Container>
        </>
    )
}

export default LoginPage;