import React from 'react';
import {
    BarChart,
    LabelList,
    Label,
    Bar,
    Brush,
    ReferenceLine,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    PieChart, Pie, Cell,
    Legend
  } from "recharts";

  const CustomBarLabel = ({ payload, x, y, width, height, value }) => (
    <text x={x + width / 2} y={y-8} fill="#666" textAnchor="middle" dominantBaseline="middle">
      {(value==0)?null:value}
    </text>
  );

  const MustDoRangeGraph = (props)=>{
    const data1 = props.data;
    data1.splice(2, 1);
    data1.forEach(item => {
      item['Range']= parseInt(item['Range']);
      item['Depth'] = parseInt(item['Depth']);
      // item['Not Fitted'] = parseInt(item['Not Fitted'] );
    });
    return(
        <>
      <h4 style={{padding:'.5rem', textAlign : 'center', backgroundColor:"#9B423C"}} className="text-light">MUST DO INVENTORY STATUS</h4>

            <BarChart
            width={900}
            height={500}
            data={data1}
            margin={{
                top: 20,
                right: 30,
                left: 20,
                bottom: 5
            }}
            >
            <CartesianGrid strokeDasharray="2 2" />
            <XAxis dataKey="name" stroke="#000000"/>
            <YAxis />
            <Tooltip />
            <Legend verticalAlign="top" wrapperStyle={{ lineHeight: "40px" }} />
            <ReferenceLine y={0} stroke="#000" />
            <Brush dataKey="name" height={30} stroke="#8884d8" />
            <Bar dataKey="Range" fill="#7bc043" stroke="#000000" barSize={70}><LabelList dataKey="Range" content={CustomBarLabel}/></Bar>
            <Bar dataKey="Depth" fill="#0392cf" stroke="#000000" barSize={70}><LabelList dataKey="Depth" content={CustomBarLabel}/></Bar>
            {/* <Bar dataKey="Not Fitted" fill="#ee4035" stroke="#000000"><LabelList dataKey="Not Fitted" content={CustomBarLabel}/></Bar> */}
            </BarChart>
        </>
        )
    }
export default MustDoRangeGraph;