  const title = `                                       Must Do Inventory Report for Tank (${ localStorage.getItem('vehicletype') === "T72" ? "T-72" : (localStorage.getItem('vehicletype') === "T90" ? "T-90" : "BMP-II") }) BA No. : ${tank}`;
  let headers;
  if (localStorage.getItem('vehicletype') === 'BMP') {
    headers = [["S No.", "MS No.",
  "Part Number","Nomenclature",
  "AU",
  "Auth for 01 Tks",
  "Issued from Ord",
  "Issued from LP",
  "Fitted","Date ","Remarks"]];
  }
  else {
    headers = [["S No.", "MS No.",
  "Part Number","Nomenclature",
  "AU",
  "Auth for 01 Tks",
  "VED",
  "Issued from Ord",
  "Issued from LP",
  "Fitted","Date ","Remarks"]];
  }

  let totalOrd = 0;
  let no =0;
  let totalLp = 0;
  let totalYesCount = 0;
  
