import {Modal,Button} from 'react-bootstrap';
import axios from 'axios';

const ChangeTableModal = (props)=>{

    const handleClose = ()=> props.module(false)

    return (
        <>
        
        <Modal show={props.show} onHide={handleClose}>
          <Modal.Header closeButton>
            <Modal.Title><p className="text-danger">Confirmation of MR Completion</p></Modal.Title>
          </Modal.Header>
          <Modal.Body>Are you confirmed?</Modal.Body>
          <Modal.Footer>
            <Button variant="primary" onClick={handleClose}>
              No
            </Button>
            <Button variant="danger" onClick={()=>{  
                var config = {
                  method: 'get',
                  url: `http://localhost:8000/api/modifytank/${props.reg}?table=${props.table}`,
                  headers: { }
                };
                
                axios(config)
                .then(function (response) {
                      window.location.reload()
              })
                .catch(function (error) {
                  console.log(error);
                });
              
             
           

              handleClose()
            }}>
              Yes
            </Button>
          </Modal.Footer>
        </Modal>
      </>
  

    )
}

export default ChangeTableModal;