import jsPDF from 'jspdf'; 
import 'jspdf-autotable';
import {useState} from 'react';
import {Button,Container,Form,Table} from 'react-bootstrap';
import axios from 'axios';

let startdate=""
let enddate=""
let truckData = []

function generate(temp){
  
    const unit = "pt";
    const size = "A4"; // Use A1, A2, A3 or A4
    const orientation = "portrait"; // portrait or landscape
  
    const marginLeft = 40;
    const doc = new jsPDF(orientation, unit, size);
  
    doc.setFontSize(15);
  
    const title = "Tank Report";
    const headers = [["Sno.", "Tank BA No.","Tank Bay Supervisor","Report Date","Departure Date"]];
  
    const data = temp.map((elem,index)=> [index+1, elem.reg,elem.manager,elem.arrival,elem.departure]);
  
    let content = {
      startY: 50,
      head: headers,
      body: data,
      bodyStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center',
      },
      headStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center'
      },
    };
  
    doc.text(title, marginLeft, 40);
    doc.autoTable(content);
    doc.save("report.pdf")
  
  }


const SearchByDate = ()=>{

    const [data,setData] = useState(null);
    return (
        <>

        <Container className="bg-dark text-light my-5 py-3">  
        <h1 className="my-2 fw-bold">Search for Tanks by Date:</h1>
     


            <Container>
            <Form className="my-3">
            <Form.Group className="col-3">
            <label>Enter Start Date:</label>
            <br/>
            
            <input onChange={(e)=>{
              startdate=e.target.value
            setData(null)
            }} type="date"/>
            </Form.Group>
            <Form.Group className="col-3">
  <label>Enter End Date:</label>
  <br/>
  <input onChange={(e)=>enddate=e.target.value} type="date"/>
</Form.Group>

  <Button onClick={()=>{
   
    var data = '';
    var config = {
      method: 'get',
      url: 'http://localhost:8000/api/trucklist',
      headers: { },
      data : data
    };
      axios(config)
      .then(function (response) {
        truckData =[]
       for(var i = 0; i < response.data.length ; i ++){
         var start = response.data[i].arrival;
         var end = response.data[i].departure;
      
         if(Date.parse(start) >= Date.parse(startdate) && Date.parse(start) <= Date.parse(enddate))
        {
          truckData.push({
            reg : response.data[i].reg,
            manager:response.data[i].manager,
           arrival : start,
           departure : end, 
          })
        }

       
       }
  
       setData(truckData)
    
      })
      .catch(function (error) {
        console.log(error);
      });


  }} className="col-2 my-2" style={{height:'20%'}}> Search</Button> 
        </Form>
        </Container>
        </Container>

        {data !== null && data.length !== 0?(
    <>
    <Container className="text-center">
            <Button 
            size="lg"
            variant="success"
            onClick={()=>{
              var temp = data
              generate(temp)

            }}>Click Here to Generate Report</Button>
            </Container>
    <Table bordered responsive variant="dark" className="mx-2 my-2">
  <thead>
    <tr>
      <th>Sno.</th>
      <th>Tank BA Number</th>
      <th>Tank Bay Supervisor</th>
      <th>Report Date</th>
      <th>Departure Date</th>
    </tr>
  </thead>
  <tbody>
  {
    data.map((elem,index)=>{
      return (
        <tr key={index}>
          <td>{index+1}</td>
          <td>{elem.reg}</td>
          <td>{elem.manager}</td>
          <td>{elem.arrival}</td>
          <td>{elem.departure}</td>
          
        </tr>
      )
    })
  }
  </tbody>
</Table></>):null}


        </>
    )
}

export default SearchByDate;