import {Container,Form,Button,Alert} from 'react-bootstrap';
import {useHistory} from 'react-router-dom';
import {useState} from 'react';
import axios from 'axios';

var FormData = require('form-data');
let name=""
let userid=""
let age=16;
let contactnumber="1234567890";
let gender="male"
let password=""
let confirmpassword=""
let rank = null
let army_number = null
let years_of_exp = null
let technical_qualifications = "Non-Tech"
let section = null
let permissions = "CO"



let alerttext=""

const RegisterPage = ()=>{

    const [show,setShow] = useState(false)
    let history = useHistory();


    function showAlert(text) {
      window.scrollTo(0, 0)
      alerttext=text;
      setShow(true)
    }

    return (
        <>
        <Alert show={show} variant="danger">
        <Alert.Heading>Some of your Details are Incorrect!</Alert.Heading>
        <p>
          Please Review following details before proceeding!
          <br/>
          {alerttext} !!
        </p>
        <hr />
        <div className="d-flex justify-content-end">
          <Button onClick={() => setShow(false)} variant="outline-danger">
            Close
          </Button>
        </div>
      </Alert>


      <Container className="bg-dark text-light my-5 py-3 rounded" style={{width:'80%'}}>
        <h2 className="fw-bold text-center my-2">Welcome to MR Process Management System</h2>
        <h4 className="mx-5 my-4">We require Following Details from you:</h4>

        <Form className="mx-3 my-3">
          <Form.Group controlId="name" className="my-2">
            <Form.Label>Name</Form.Label>
            <Form.Control type="text" placeholder="Enter your Name" onChange={(e)=>{name=e.target.value}}/>
          </Form.Group>

          
          <Form.Group controlId="name" className="my-2">
            <Form.Label>User ID</Form.Label>
            <Form.Control type="text" placeholder="Enter any username" onChange={(e)=>{userid=e.target.value}} />
          </Form.Group>
          
          
      
   
          <Form.Group controlId="gender" className="my-2">
            <Form.Label>System Privileges</Form.Label>
            <Form.Control as="select" onChange={(e)=>{permissions=e.target.value}}>
              <option>CO</option>
              <option>OIC MR</option>
              <option>Supervisor</option>
            </Form.Control>
          </Form.Group>
            
              
          

          <Form.Group controlId="name" className="my-2">
            <Form.Label>Rank</Form.Label>
            <Form.Control type="text" placeholder="Enter your Rank" onChange={(e)=>{rank=e.target.value}} />
          </Form.Group>


          
          <Form.Group controlId="name" className="my-2">
            <Form.Label>Section</Form.Label>
            <Form.Control type="text" placeholder="Enter your Section" onChange={(e)=>{section=e.target.value}} />
          </Form.Group>


          <Form.Group controlId="name" className="my-2">
            <Form.Label>Army Number</Form.Label>
            <Form.Control type="text" placeholder="Enter your Army Number" onChange={(e)=>{army_number=e.target.value}} />
          </Form.Group>

          <Form.Group controlId="name" className="my-2">
            <Form.Label>Years of Experience</Form.Label>
            <Form.Control type="number" placeholder="Enter your Years of Experiencee" onChange={(e)=>{years_of_exp=e.target.value}} />
          </Form.Group>

  

         
          <Form.Group controlId="gender" className="my-2">
            <Form.Label>Technical Qualifications</Form.Label>
            <Form.Control as="select" onChange={(e)=>{technical_qualifications=e.target.value}}>
              <option>Non-Tech</option>
              <option>Grade 1</option>
              <option>Grade 2</option>
              <option>Grade 3</option>
              <option>Diploma</option>
              
            </Form.Control>
          </Form.Group>

          <Form.Group controlId="retypepassword" className="my-2">
            <Form.Label>Password</Form.Label>
            <Form.Control type="password" placeholder="Password" onChange={(e)=>{password=e.target.value}}/>
          </Form.Group>


          <Form.Group controlId="retypepassword" className="my-2">
            <Form.Label>Retype Password</Form.Label>
            <Form.Control type="password" placeholder="Password" onChange={(e)=>{confirmpassword=e.target.value}}/>
          </Form.Group>

          <Button
          
            variant="success"
            className="btn-lg my-3"
            onClick={()=>{
           
                setShow(false)
                setTimeout(function (){
                  if(name=== "")
              showAlert("Name Missing")
              else if(userid==="")
              showAlert("User ID Missing")
              else if(age===null)
              showAlert("Age is Missing")
              else if(gender==="")
              showAlert("Gender is not Selected")
              else if (contactnumber==="")
              showAlert("Contact Number is Missing")
              else if(password === "")
              showAlert("Password Missing")
              else if(password !== confirmpassword)
              showAlert("Passwords do not match")
              else if(army_number === null)
              showAlert("Army Number Missing!")
              else if(rank === null)
              showAlert("Rank is Missing")
              else if(years_of_exp === null)
              showAlert("Years of Experience Missing !")
              else if(section === null)
              showAlert("Section Missing !!")
      

              else{


                var data = new FormData();
            data.append('username', userid);
            data.append('first_name', name);
            data.append('last_name', "temp");
            data.append('password', password);
            data.append('confirmpass', confirmpassword);
            data.append('age', age);
            data.append('contactnumber', contactnumber);
            data.append('gender', gender);
            data.append('rank',rank);
            data.append('army_number',army_number);
            data.append('years_of_exp',years_of_exp);
            data.append('technical_qualifications',technical_qualifications);
            data.append('section',section);
            data.append('level',permissions)
          
            async function sendpostRequest(){
              try{
            await axios.post('http://localhost:8000/api/register',data,{
                  headers:{'Content-Type': 'application/json',},
                data: data
                })
                history.push({
                  pathname:'/success',
                  state:{
                    id:userid,
                    password:password,
                  }
                })
                }catch(e)
                  {
                    showAlert("User ID Already Exists")
                      }
                    }
           sendpostRequest()   
              }
                
                }, 1000)
            }}
          >
            Register
          </Button>
        </Form>
      </Container>
        </>
    )
}

export default RegisterPage;