import {Modal,Button} from 'react-bootstrap';
import {useState} from 'react';

const ActivityCheckModal = (props)=>{

    const [show,setShow] = useState(true)
    const handleClose = ()=>setShow(false)


    return (
        <>
        
      <Modal show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title><p className="text-danger">Unauthorized</p></Modal.Title>
        </Modal.Header>
        <Modal.Body>Sorry! You can't edit this section now! <br/>
        <strong>Your Permission Level : {props.perm} </strong><br/>
        <strong> Activity Delayed By {props.delay} days </strong>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleClose}>
            Close
          </Button>
        
        </Modal.Footer>
      </Modal>
        </>
    )
}

export default ActivityCheckModal;