import {Container,Table,Spinner,Button} from 'react-bootstrap';
import {useEffect,useState} from 'react';
import axios from 'axios';
import jsPDF from 'jspdf'; 
import 'jspdf-autotable';

function convertDate(inputFormat) {
  function pad(s) { return (s < 10) ? '0' + s : s; }
  var d = new Date(inputFormat)
  return [pad(d.getDate()), pad(d.getMonth()+1), d.getFullYear()].join('/')
}


function generate(temp,user) {  

    const unit = "pt";
    const size = "A4"; // Use A1, A2, A3 or A4
    const orientation = "portrait"; // portrait or landscape
  
    const marginLeft = 40;
    const doc = new jsPDF(orientation, unit, size);
    doc.setFont(undefined, 'bold')

    doc.setFontSize(15);
  
    const title = `USER DELAY REPORT FOR USER : ${user}`;
    const headers = [["S No.", "Tank BA No.","Username","Cause","Delay (Days)","Addl Activity to Counteract Delay","Delay Reduced","Remarks","Time Stamp"]];
  
    const data = temp.map((elem,index)=> {
        let delay="",addlactivity="",remarks="",delayreduction=""
        try{delay = elem.info.split('delay')[2].split(',')[0]}catch(e){}
        try{addlactivity = elem.info.split('addl_activity')[1].split(',')[0]}catch(e){}
        try{delayreduction = elem.info.split('delay_reduction')[1].split(',')[0] }catch(e){}
        try{remarks = elem.info.split('remarks')[1].trim()}catch(e){}
        if(remarks === "None") remarks = ""
  
      return [index+1, 
      elem.truck,
      user,
      elem.reason,
      delay,
        addlactivity,
        delayreduction,
        remarks,
        convertDate(elem.timestamp.split(',')[0])];
      });
    
    let content = {
      startY: 50,
      head: headers,
      body: data,
      theme : "grid",
      styles : {
        halign : "left",
      },
      bodyStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center',
      },
      headStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center'
      },
    };
  
    doc.text(title, marginLeft, 40);
    doc.autoTable(content);
    doc.save("report.pdf")
  }  

const UserDelayReport = (props)=>{

    const [data,setData] = useState(null)

    
    useEffect(()=>{

      

        var config = {
          method: 'get',
          url: `http://localhost:8000/api/delaytablehistory?username=${props.id}`,
          headers: { 
            'Content-Type': 'application/json'
          },
        };
        
        axios(config)
        .then(function (response) {
            setData(response.data)
        })
        .catch(function (error) {
          console.log(error);
        });
        
        // eslint-disable-next-line
    },[])


    return (
        <>
        <Container>
        {data !== null? (
            <>
            <Table striped bordered hover variant="dark">
  <thead>
    <tr>
      <th>S No. </th>
      <th>Tank BA No.</th>
      <th>Username</th>
      <th>Cause</th>
      <th>Delay (Days)</th>
      <th>Addl Activity to Counteract Delay</th>
      <th>Delay Reduced (Days)</th>
      <th>Remarks</th>
      <th>Time Stamp</th>
    </tr>
  </thead>
  <tbody>
  {data.map((elem,index)=>{

    let delay="",addlactivity="",remarks="",delayreduction=""
    try{delay = elem.info.split('delay')[2].split(',')[0]}catch(e){}
    try{addlactivity = elem.info.split('addl_activity')[1].split(',')[0]}catch(e){}
    try{delayreduction = elem.info.split('delay_reduction')[1].split(',')[0] }catch(e){}
    try{remarks = elem.info.split('remarks')[1].trim()}catch(e){}
    if(remarks === "None") remarks = ""

      return (
        <tr>
      <td>{index + 1}</td>
      <td>{elem.truck}</td>
      <td>{props.name}</td>
      <td>{elem.reason}</td>
      <td>{delay}</td>
      <td>{addlactivity}</td>
      <td>{delayreduction}</td>
      <td>{remarks}</td>
      <td>{convertDate(elem.timestamp.split(',')[0])}</td>
    </tr>
      )
  })}
    
    
  </tbody>
</Table>
            </>
        ): (
            <>
            <Spinner animation="border" role="status">
                <span className="visually-hidden">Loading...</span>
                </Spinner>
               </>
        )}
        <Button variant="success" onClick={()=>{
          generate(data,props.name)
        }}>Generate Report</Button>
       
        </Container>
        </>
    )
}

export default UserDelayReport;