import {Modal,Button, Form} from 'react-bootstrap';
import { useState } from 'react';
import axios from 'axios';

let reason = null;
const AddDelayItemModal = (props)=>{

    const [val, setVal] = useState(false);

    const handleClose = ()=>props.module(false);

    return (
        <Modal show={props.show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>Add New Item in Delay Table</Modal.Title>
        </Modal.Header>
        <Modal.Body>
        <Form.Group className="mb-3" controlId="formBasicEmail">
        <Form.Label>Reason for Delay</Form.Label>
        <Form.Control onChange={(e)=>reason = e.target.value} type="text" />
      </Form.Group>
      {val?<h5 className="fw-bold text-danger">Please Make Sure Reason is not missing!!</h5> : null}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleClose}>
            Close
          </Button>
          <Button variant="primary" onClick={()=>{
            if(reason === null)
              setVal(true);
            else {
              setVal(false);
              var data = JSON.stringify({
                "reason": reason
              });
              
              var config = {
                method: 'post',
                url: `http://localhost:8000/api/delaytable/${props.reg}`,
                headers: { 
                  'Content-Type': 'application/json'
                },
                data : data
              };
              
              axios(config)
              .then(function (response) {
                  props.load(true)
                  handleClose()
              })
              .catch(function (error) {
                console.log(error);
              });
              
            }
          }}>
            Save
          </Button>
        </Modal.Footer>
      </Modal>
    )
}

export default AddDelayItemModal;