import { useState,useEffect } from "react"
import {Table,Button,Spinner} from 'react-bootstrap';
import jsPDF from 'jspdf'; 
import 'jspdf-autotable';
import axios from 'axios';

function generate(temp,tank) {  

    const unit = "pt";
    const size = "A4"; // Use A1, A2, A3 or A4
    const orientation = "portrait"; // portrait or landscape

    const marginLeft = 40;
    const doc = new jsPDF(orientation, unit, size);
    doc.setFont(undefined, 'bold')

    doc.setFontSize(15);

    const title = `Activity Report for Tank BA No ${tank}`;
    const headers = [["S No","Updated By","Info","Completed","Reason","TimeStamp"]];

    const data = temp.map((elem,index)=> {
      
      let completed = "";
      let item = "";
      let reason = "";
      
      try{item = elem.info.split('of truck')[0].split('item:')[1]}catch(e){}
      try {completed= "Completed" + elem.info.split('completed')[1].split('by:')[0]}catch(e){}
      try{reason = elem.info.split("reason :")[1].split("'")[0]}catch(e){}

      if (reason === " None") {
        reason = "";
      }
      if (completed === "Completed removed ") {
        completed = "";
      }
      else {
        console.log(completed);
      }

      return [index+1, elem.updatedby,item,completed,reason,elem.timestamp.split(',')[0]]
    
    });

    let content = {
      startY: 50,
      head: headers,
      body: data,
      theme : "grid",
      styles : {
        halign : "left",
      },
      bodyStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center',
      },
      headStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center'
      },
    };

    doc.text(title,doc.internal.pageSize.getWidth() / 2, 20, { align: "center" });
    doc.autoTable(content);
    doc.save("report.pdf")
}  





const ActivityReport = (props)=>{

    const [data,setData] = useState(null)

    useEffect(()=>{
        var config = {
            method: 'get',
            url: `http://localhost:8000/api/fetchlogs/${props.reg}`,
            headers: { },
          };

          axios(config)
          .then(function (response) {

              const newData = response.data.filter((elem) => {
                let completed;
                try {completed= "Completed" + elem.info.split('completed')[1].split('by:')[0]}catch(e){}
                return (completed !== "Completed removed " );
              });
              // setData(response.data)
              setData(newData);
              
          })
          .catch(function (error) {
            console.log(error);
       
          });
          // eslint-disable-next-line
    },[])

    return (
        <>
           {data!== null ?(
            <>
            <Table className="mx-3 my-2" responsive striped bordered variant="dark">
  <thead>
    <tr>
    <th>S No </th>
      <th>Tank BA No</th>
      <th>User</th>
      <th>Info</th>
      <th>Completed</th>
      <th>Reason</th>
      <th>Time Stamp</th>
    </tr>
  </thead>
  <tbody>
  {data.map((elem,index)=>{
  let completed = "";
  let item = "";
  let reason = ""
  try{item = elem.info.split('of truck')[0].split('item:')[1]}catch(e){}
  try {completed= "Completed" + elem.info.split('completed')[1].split('by:')[0]}catch(e){}
  try{reason = elem.info.split("reason :")[1].split("'")[0]}catch(e){}
  
  return (
    <tr key={index}>
      <td>{index+1}</td>
      <td>{props.reg}</td>
      <td>{elem.updatedby}</td>
      <td>{item}</td>
      <td>{completed==="Completed removed "?"":completed}</td>
      <td>{reason===" None"?"":reason}</td>
      <td>{elem.timestamp.split(',')[0]}</td>
    </tr>
    )
  })}
   
  
  </tbody>
</Table>
<Button className="mx-5 my-5" onClick={()=>{
    generate(data,props.reg)
}}>Click to Generate Report</Button>
</>):<Spinner animation="border" role="status">
    <span className="visually-hidden">Loading...</span>
    </Spinner>}
        </>
    )
}

export default ActivityReport;