import { Button, Container, Spinner } from "react-bootstrap";
import { Link, useLocation, useParams } from 'react-router-dom';
import { useState, useEffect,  } from 'react';
import axios from 'axios';
import ZigZagTimeLine from '../components/ZigZagTimeLine'


let departure_date = null,estimatedepart = null

async function getTruckData(truckid){
    let res;
    try{
      res = await axios.get(`http://localhost:8000/api/truck/${truckid}`)
      return res.data;
    }catch(error){
      return "error"
    }
    
  } 

const UserTruckDashBoard = ()=>{
    const location = useLocation()
    const { scroll } = useParams();
    

const [data,setData] = useState(null);


useEffect(() => {
  // Scrolling to the y-location from the header
  if (scroll) {
      window.scrollTo({
        top: scroll,
        behavior: 'instant'
      });
  }
}, [data]);


useEffect(() => {
    if(location.state !== undefined){
    getTruckData(location.state).then((res)=>{
      departure_date = new Date(res.truck.timestamp)
      estimatedepart = new Date(res.truck.timestamp)
      if(localStorage.getItem('vehicletype') === "T90")  {
        departure_date.setDate(departure_date.getDate() + 52 - 1);
        estimatedepart.setDate(estimatedepart.getDate() + 76);
      }
      else if(localStorage.getItem('vehicletype') === "T72")  {
        departure_date.setDate(departure_date.getDate() + 53 - 1);
        estimatedepart.setDate(estimatedepart.getDate() + 74);
      }
      else {
        departure_date.setDate(departure_date.getDate() + 43 - 1);
        estimatedepart.setDate(estimatedepart.getDate() +68);
      }
      setData(res)
      
       
    }).catch((error)=>{
      console.log(error);
    })
    }
  

// eslint-disable-next-line react-hooks/exhaustive-deps
},[]);


    return (
    
        <>
      
   {localStorage.getItem('id') !== null && location.state !== undefined? (
     <>
    {data===null?(<Container className="text-center my-5">
        <Spinner animation="border" variant="success" />
        </Container>):<>
  
        <Container className="text-light bg-dark my-5 py-4">
        <Link to="/maintruckdb"><Button size="lg" className="mx-2" variant="success" style={{float:'right'}}>Go Back</Button></Link>
        <Link to="/"><Button size="lg" variant="danger" style={{float:'right'}}>Logout</Button></Link>
        <h2 className="fw-bold"> Welcome User, {atob(localStorage.getItem("name"))}</h2>
        <Container>
        <h4 > Tank BA No. : {location.state} &nbsp;&nbsp;&nbsp;   Tank Bay Supervisor : {data.truck.manager}</h4>
        <h4 > Date In : {data.truck.timestamp} &nbsp;&nbsp;&nbsp; Planned Bay Out Date : {departure_date.toDateString()}</h4>
        <h4>Estimate Departure Date : {estimatedepart.toDateString()}</h4>
        <h5>Legend: </h5>
       
        </Container>
        <Button className="mx-2 my-2 green" size="sm" >On Schedule</Button>
        <Button className="mx-2 my-2 yellow" size="sm" >Pending (1 Day)</Button>
        <Button className="mx-2 my-2 orange" size="sm" >Pending (2 Days)</Button>
        <Button className="mx-2 my-2 purple" size="sm" >Pending (3 Days)</Button>
        <Button className="mx-2 my-2 brick" size="sm" >Pending (4&gt; Days)</Button>
        <Button className="mx-2 my-2" size="sm" variant="secondary">ADDL</Button>
        </Container>
          {/* <TimeLine reg={data.truck.regno} items={data.items} arrival={data.truck.timestamp}/> */}
          <ZigZagTimeLine 
          
          manager = {data.truck.manager}
          batchout={data.truck.batchout}
          timestamp={data.truck.timestamp}
          estimatedepart={data.truck.estimatedepart}
          reg={data.truck.regno} items={data.items} arrival={data.truck.timestamp} status = {data.status}/>
        </>}
</>
  
   ) : (
     <h1 className="mx-2 my-3 text-center fw-bold"> It seems You Are Lost !! Click Here to Go Back!!
     <br/>
     <Link to="/maintruckdb" ><Button size="lg" variant="success">Home Page</Button></Link>
     </h1>
   )}


        </>
    )
}

export default UserTruckDashBoard;