import {Button, Modal, Form} from 'react-bootstrap';
import axios from 'axios';
import {useState} from 'react';

let text = null;
const AddRotablesModal = (props)=>{


    const handleClose = () => props.module(false);
    const [error, setError] = useState(false);
  
    return (
        <>
         <Modal show={props.show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>Add New Rotable Item</Modal.Title>
        </Modal.Header>
        <Modal.Body>
        <Form.Group className="mb-3" controlId="formBasicPassword">
        <Form.Label>Rotable Item Nomenclature</Form.Label>
        <Form.Control onChange={(e)=>text = e.target.value} type="text" placeholder="ex: Laser Beam" />
      </Form.Group>
      {error?<h5 className="fw-bold" style={{color : 'red'}}>Error : Nomenclature Missing</h5>:null}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleClose}>
            Close
          </Button>
          <Button variant="primary" onClick={()=>{
            if(text === null) setError(true)
            else setError(false);

            if(text !== null){
              var data = JSON.stringify({
              "name": text
            });
            
            var config = {
              method: 'post',
              url: `http://localhost:8000/api/addrotable/${props.reg}`,
              headers: { 
                'Content-Type': 'application/json'
              },
              data : data
            };
            
            axios(config)
            .then(function (response) {
            handleClose()
            props.loadmodule(true)
            })
            .catch(function (error) {
              console.log(error);
            });
            }
            
            
            
          }}>
            Save Changes
          </Button>
        </Modal.Footer>
      </Modal>
        </>
    )
}

export default AddRotablesModal;