function generate(temp,tank,totalDelay,totalDelayReduction) {  

    const unit = "pt";
    const size = "A4"; // Use A1, A2, A3 or A4
    const orientation = "portrait"; // portrait or landscape
  
    const marginLeft = 40;
    const doc = new jsPDF(orientation, unit, size);
    doc.setFont(undefined, 'bold')

    doc.setFontSize(15);
  
    const title = `TANK DELAY REPORT TANK BA No : ${tank}`;
    const headers = [["S No","Username","Reason","Delay (In Days)","Addl Activity to Counteract Delay","Delay Reduction","Remarks","Time Stamp"]];
    console.log("delay total data is ",temp)
    temp = temp.map(obj => {
    const delayMatch = obj.info.match(/delay\s(\d+)/);
    const delayRed = obj.info.match(/delay_reduction\s(\d+)/);
    const delay = delayMatch ? parseInt(delayMatch[1], 10) : null;
    const delay_reduced = delayRed ? parseInt(delayRed[1], 10) : null;
    if(delay!== 0 || delay_reduced !== 0){
      return obj
    }
    }).filter(obj => obj);

    console.log("the new data is :"+ temp)
    
    const data = temp.map((elem,index)=> {
        let delay="",addlactivity="",remarks="",delayreduction=""
        try{delay = elem.info.split('delay')[2].split(',')[0]}catch(e){}
        try{addlactivity = elem.info.split('addl_activity')[1].split(',')[0]}catch(e){}
        try{delayreduction = elem.info.split('delay_reduction')[1].split(',')[0] }catch(e){}
        try{remarks = elem.info.split('remarks')[1]}catch(e){}
        // console.log(delay)
        // console.log((delay===" 0")?"yes":"no")
        // if (delay===" 0" && delayreduction===" 0") {
        //   return;
        // }
      return [index+1, elem.user,elem.reason,
        delay,
        addlactivity,
        delayreduction,
        remarks,
        convertDate(elem.timestamp.split(',')[0])]
    
    });
    data.push(["","No. of Days","",totalDelay,"","",totalDelayReduction,""])
    let content = {
      startY: 50,
      head: headers,
      body: data,
      theme : "grid",
      styles : {
        halign : "left",
      },
      bodyStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center',
      },
      headStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center'
      },
    };
  
    doc.text(title,  doc.internal.pageSize.getWidth() / 2, 20, { align: "center" });
    doc.autoTable(content);
    doc.setLineWidth(2);
    doc.autoTable({
      head: [[`Net Delay (in Days) : ${totalDelay - totalDelayReduction}`]],
  }); 
    doc.save("inventoryreport.pdf")
  }  
