import AssemblyLinePhase from './AssemblyLinePhase';
import {Nav,Container} from 'react-bootstrap';
import {useState,useEffect} from 'react';
import EntryPhase from './EntryPhase';

const CouldDoInventory = (props)=>{

    const [tab,setTab] = useState(1)
   
    useEffect(()=>{
      if(localStorage.getItem('phase') === null)
      localStorage.setItem('phase','entry')
  
      if(localStorage.getItem('phase') === 'entry')
      setTab(1)
      else if(localStorage.getItem('phase') === 'repair')
      setTab(2)
  
    },[])

  
  return (
    <>
    <Container className="mx-4">
    {/* <h3 className="fw-bold mx-5">Current Phase : </h3> */}
    </Container>
    <Container className="mx-5 my-5 bg-success fw-bold">
    <Nav variant="tabs" activeKey={tab}>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link onClick={()=>{
        localStorage.setItem('phase','entry')
      setTab(1)
    }} eventKey={1} className="text-dark" >Initial Phase</Nav.Link>
  </Nav.Item>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link onClick={()=>{
      localStorage.setItem('phase','repair')
      setTab(2)
    }} className="text-dark"  eventKey={3} >
      Repair Phase
    </Nav.Link>
  </Nav.Item>
</Nav>
</Container>
{tab === 1?<EntryPhase
  reg={props.reg}
/> : null}
{tab === 2?     <AssemblyLinePhase
    reg = {props.reg}

    /> : null}

    </>
  )
}

export default CouldDoInventory;