import 'jspdf-autotable';
import CouldDoRangeGraph from './CouldDoRangeGraph';
function convertDate(inputFormat) {
  if(inputFormat==""){
      return('');
  }
  function pad(s) { return (s < 10) ? '0' + s : s; }
  var d = new Date(inputFormat)
  return [pad(d.getDate()), pad(d.getMonth()+1), d.getFullYear()].join('/')
}
function generate(temp,tank) {  

  const unit = "pt";
  const size = "A3"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);
  doc.setFont(undefined, 'bold')

  doc.setFontSize(15);

  const title = `Could Do Inventory Report for Tank BA No : ${tank}`;
  const headers = [["S No", "Updated By","MS No","Part Number","Nomenclature","VED","AU","Auth for 01 Tks","Fitted","Issued from Ord","Issued from LP","Date","Remarks","TimeStamp"]];
  
  const data = temp.map((elem,index)=> {
    let fitted="",remarks="",issuedfromexord="",issuedfromlp="",date=""
    try{fitted=elem.info.split('fitted')[1].split(',')[0]}catch(e){}
    try{remarks=elem.info.split('remarks')[1].split(':')[1].split('for')[0].trim()}catch(e){}
    try{issuedfromexord=elem.info.split('issuedfromexord')[1].split(':')[1].split(',')[0]}catch(e){}
    try{issuedfromlp=elem.info.split("issuedfromlp")[1].split(":")[1].split(",")[0]}catch(e){}
    try{date = elem.info.split("date :")[1].trim()}catch(e){}
    if(remarks === "None") remarks = ""
    if(date === "None") date = ""
    fitted = (fitted==" yes" || fitted==" Yes")?"Yes":"No"

    return [index+1, elem.user,elem.msno,elem.partno,elem.item,elem.ved,elem.au, elem.authfor01tks,fitted,issuedfromexord,issuedfromlp,convertDate(date),remarks,convertDate(elem.timestamp.split(',')[0])]
  
  });
  let totalOrd = 0;
  let totalLp = 0;
  let totalYesCount = 0;
  let totalNoCount = 0;

  data.forEach((elem)=>{
    if(elem[8] === "Yes") {
      totalYesCount++;
      if (elem[9] && elem[9]>0) {
        totalOrd++;
      }
      if (elem[10] && elem[10]>0) {
        totalLp++;
      }
    }
    else{
      totalNoCount++;
    }
    
  })
  let content = {
    startY: 50,
    head: headers,
    margin : {left : 4},
    body: data,
    theme : "grid",
    styles : {
      halign : "left",
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    },
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
    columnStyles: {
      0: {cellWidth: 35},
      1: {cellWidth: 80},
      2: {cellWidth: 30},
      3: {cellWidth: 110},
      4: {cellWidth: 120},
      5: {cellWidth: 30},
      6 : {cellWidth : 35},
      7: {cellWidth: 42},
      8: {cellWidth: 42},
      9: {cellWidth: 44},
      10: {cellWidth: 44},
      11: {cellWidth: 70},
      12: {cellWidth: 70},
      13: {cellWidth: 80},
      
    }
  };

  doc.text(title,doc.internal.pageSize.getWidth() / 2, 20, { align: "center" });
  doc.autoTable(content);
  doc.autoTable({
    head: [["Yes","No","Total Issued from Ord", "Total Issued from LP"]],
    body: [[totalYesCount,totalNoCount,totalOrd,totalLp]],
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
      fontStyle: 'bold'
    },
    columnStyles: {
      0: {cellWidth: 70},
      1: {cellWidth: 70},
      2: {cellWidth: 300},
      3: {cellWidth: 300},
      
    }
});
  doc.save("inventoryreport.pdf")
}  





  

