function generate(temp,tank) {  

  const unit = "pt";
  const size = "A4"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);
  doc.setFont(undefined, 'bold')

  doc.setFontSize(15);

  const title = `                     STATE OF ROTABLES REPAIR : ${tank}`;
  const headers = [["S No", "Item","Date Out","Date In","Action Taken","Fitted By","Checked By","Working Days"]];

  const data = temp.map((elem,index)=> {

    let datein = "",dateout = ""

    if(elem.datein !== null){
      let ddatein = new Date(elem.datein)
      ddatein.setDate( ddatein.getDate() - 1 );
      datein = convertDate(ddatein)
    }else datein = "-"
    if(elem.dateout !== null){
      let ddateout = new Date(elem.dateout)
      ddateout.setDate( ddateout.getDate() - 1 );
      dateout =convertDate(ddateout)
    }else dateout = "-"
  
  
    return [index+1, elem.item,datein,dateout,elem.eqptstatus,elem.fittedby,elem.checkedby,elem.workingdays];
  
  });

  let content = {
    startY: 50,
    head: headers,
    body: data,
    theme : "grid",
    styles : {
      halign : "center",
      // fontStyle : 'bold'
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    },
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
 
  };

  doc.text(title, marginLeft, 40).setFont(undefined,10)
  doc.autoTable(content);
  doc.setLineWidth(2);

  doc.save("report.pdf")

}  


