function formatDate(date) {
  var d = new Date(date),
      month = '' + (d.getMonth() + 1),
      day = '' + d.getDate(),
      year = d.getFullYear();

  if (month.length < 2) 
      month = '0' + month;
  if (day.length < 2) 
      day = '0' + day;

  return [day, month, year].join('-');
}

function convertDate(inputFormat) {
  function pad(s) { return (s < 10) ? '0' + s : s; }
  var d = new Date(inputFormat)
  return [pad(d.getDate()), pad(d.getMonth()+1), d.getFullYear()].join('/')
}

function generate(temp,tank) {  

  const unit = "pt";
  const size = "A4"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);
  doc.setFont(undefined, 'bold')

  doc.setFontSize(15);

  const title = `Rotable Item History Report for Tank BA No : ${tank}`;
  const headers = [["S No", "Updated By","Item","Date Out","Date In","Eqpt Status","Fitted By","Working Days","TimeStamp"]];

  const data = temp.map((elem,index)=> {
    let datein="-",dateout="-",eqptstatus="",workingdays="",fittedby=""
    try{  if(elem.info.split('datein to:')[1].split(',')[0].trim()==="None"){
          datein="  -"
  } 
          else{
            datein=new Date(elem.info.split('datein to:')[1].split(',')[0].trim())
            datein.setDate(datein.getDate()-1);
            datein = formatDate(datein);      
  }
    }catch(e){}
    try{if(elem.info.split('dateout to:')[1].split(',')[0].trim()==="None"){
            dateout="   -"
        } 
        else{
          dateout=new Date(elem.info.split('dateout to:')[1].split(',')[0].trim())
          dateout.setDate(dateout.getDate()-1);
          dateout = formatDate(dateout);      
        }
    }catch(e){}
    try{eqptstatus=elem.info.split('eqptstatus to:')[1].split(',')[0]}catch(e){}
    try{workingdays=elem.info.split('workingdays to:')[1].split(',')[0]}catch(e){}
    try{fittedby = elem.info.split('fittedby to:')[1].split(',')}catch(e){}
    return [index+1, elem.user,elem.item,dateout,datein,eqptstatus,fittedby,workingdays,
      
      convertDate(elem.timestamp.split(',')[0])]
    
  });

  let content = {
    startY: 50,
    head: headers,
    body: data,
    theme : "grid",
    styles : {
      halign : "left",
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    },
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
  };

  doc.text(title,doc.internal.pageSize.getWidth() / 2, 20, { align: "center" });
  doc.autoTable(content);
  doc.save("report.pdf")
}  


