import {Container} from 'react-bootstrap';
import deepClone from 'deep-clone';
import {useHistory,useLocation} from 'react-router-dom';


let tday,tdate,treg

const ZigZagTimeLine = (props)=>{

  let values = []
  let status = props.status

  const history  = useHistory()
  const location = useLocation()

  let temp = new Date(Date.parse(props.arrival))

  if(localStorage.getItem('vehicletype') === "T90"){

    let pending_portion = false;
  for(var i = 0; i < 56 ; i ++){
      let date = new Date(temp)
      date.setDate(temp.getDate() + i )
      let tasks = []

      for(var j = 0; j < props.items.length; j ++){
        if(props.items[j].completed === false) {
          if(props.items[j].itemdesc !== undefined && props.items[j].itemdesc.day === i + 1)
          pending_portion = true;
          else if(props.items[j].itemdesc === undefined && props.items[j].day === i + 1)
          pending_portion = true
        }
          
          if(props.items[j].itemdesc !== undefined && props.items[j].itemdesc.day === i + 1){
              date = new Date(Date.parse(props.items[j].deadline))
              tasks.push({
                  id : props.items[j].id,
                  truck : props.items[j].truck,
                  itemdesc : props.items[j].itemdesc,
                  reason: props.items[j].reason,
                  reasonby : props.items[j].reasonby,
                  completed: props.items[j].completed,
                  completedby: props.items[j].completedby,
                  deadline : props.items[j].deadline
  
                 })
          }
         

          else if (props.items[j].itemdesc === undefined && props.items[j].day === i + 1){
            date = new Date(Date.parse(props.items[j].deadline))
              tasks.push({
                  id : props.items[j].id,
                  truck : props.items[j].truck,
                  // itemdesc : props.items[j].itemdesc,
                  itemdesc : {
                    day : props.items[j].day, 
                    activity : props.items[j].activity, 
                    time : props.items[j].time, 
                    noofteck : props.items[j].noofteck,   
                  },
                  reason: props.items[j].reason,
                  reasonby : props.items[j].reasonby,
                  completed: props.items[j].completed,
                  completedby: props.items[j].completedby,
                  deadline : props.items[j].deadline
  
                 })
          }

          
      }
      if(date.getDate() === new Date().getDate() && date.getMonth()   === new Date().getMonth() && new Date().getFullYear() === date.getFullYear())
                                status="primary"
      else if(date > new Date()) status ="secondary"
      else if(pending_portion === false) status = "success"
      else status = props.status

    if(tasks.length !== 0)                
      values.push({
        day : i + 1,
          title : temp.toLocaleDateString(),
          main_data : date, 
          status : status,
          task : deepClone(tasks),
  
      })
  }
}

  else if(localStorage.getItem('vehicletype') === "BMP"){
    let pending_portion = false
  for(var i = 0; i < 48 ; i ++){
    let date = new Date(temp)
    date.setDate(temp.getDate() + i )
    let tasks = []

    for(var j = 0; j < props.items.length; j ++){
      if(props.items[j].completed === false) {
        if(props.items[j].itemdesc !== undefined && props.items[j].itemdesc.day === i + 1)
        pending_portion = true;
        else if(props.items[j].itemdesc === undefined && props.items[j].day === i + 1)
        pending_portion = true
      }
        
        if(props.items[j].itemdesc !== undefined && props.items[j].itemdesc.day === i + 1){
            date = new Date(Date.parse(props.items[j].deadline))
            tasks.push({
                id : props.items[j].id,
                truck : props.items[j].truck,
                itemdesc : props.items[j].itemdesc,
                reason: props.items[j].reason,
                reasonby : props.items[j].reasonby,
                completed: props.items[j].completed,
                completedby: props.items[j].completedby,
                deadline : props.items[j].deadline

               })
        }
       

        else if (props.items[j].itemdesc === undefined && props.items[j].day === i + 1){
          date = new Date(Date.parse(props.items[j].deadline))
            tasks.push({
                id : props.items[j].id,
                truck : props.items[j].truck,
                // itemdesc : props.items[j].itemdesc,
                itemdesc : {
                  day : props.items[j].day, 
                  activity : props.items[j].activity, 
                  time : props.items[j].time, 
                  noofteck : props.items[j].noofteck,   
                },
                reason: props.items[j].reason,
                reasonby : props.items[j].reasonby,
                completed: props.items[j].completed,
                completedby: props.items[j].completedby,
                deadline : props.items[j].deadline

               })
        }

        
    }
    if(date.getDate() === new Date().getDate() && date.getMonth()   === new Date().getMonth() && new Date().getFullYear() === date.getFullYear())
                              status="primary"
    else if(date > new Date()) status ="secondary"
    else if(pending_portion === false) status = "success"
    else status = props.status
    if(tasks.length !== 0)            
    values.push({
      day : i + 1,
        title : temp.toLocaleDateString(),
        main_data : date, 
        status : status,
        task : deepClone(tasks),

    })
}
  }


  else if(localStorage.getItem('vehicletype') === "T72"){
    let pending_portion = false;

  for(var i = 0; i < 54 ; i ++){
    let date = new Date(temp)
    date.setDate(temp.getDate() + i )
    let tasks = []
    for(var j = 0; j < props.items.length; j ++){
        if(props.items[j].completed === false) {
          if(props.items[j].itemdesc !== undefined && props.items[j].itemdesc.day === i + 1)
          pending_portion = true;
          else if(props.items[j].itemdesc === undefined && props.items[j].day === i + 1)
          pending_portion = true
        }
        if(props.items[j].itemdesc !== undefined && props.items[j].itemdesc.day === i + 1){
            date = new Date(Date.parse(props.items[j].deadline))
            tasks.push({
                id : props.items[j].id,
                truck : props.items[j].truck,
                itemdesc : props.items[j].itemdesc,
                reason: props.items[j].reason,
                reasonby : props.items[j].reasonby,
                completed: props.items[j].completed,
                completedby: props.items[j].completedby,
                deadline : props.items[j].deadline

               })
        }
       

        else if (props.items[j].itemdesc === undefined && props.items[j].day === i + 1){
          date = new Date(Date.parse(props.items[j].deadline))
            tasks.push({
                id : props.items[j].id,
                truck : props.items[j].truck,
                // itemdesc : props.items[j].itemdesc,
                itemdesc : {
                  day : props.items[j].day, 
                  activity : props.items[j].activity, 
                  time : props.items[j].time, 
                  noofteck : props.items[j].noofteck,   
                },
                reason: props.items[j].reason,
                reasonby : props.items[j].reasonby,
                completed: props.items[j].completed,
                completedby: props.items[j].completedby,
                deadline : props.items[j].deadline

               })
        }

        
    }
    if(date.getDate() === new Date().getDate() && date.getMonth()   === new Date().getMonth() && new Date().getFullYear() === date.getFullYear())
                              status="primary"
    else if(date > new Date()) status ="secondary"
    else if(pending_portion === false) status = "success"
    else status = props.status

    if(tasks.length !== 0)         
    values.push({
      day : i + 1,
        title : temp.toLocaleDateString(),
        main_data : date, 
        status : status,
        task : deepClone(tasks),

    })
}
 
  }

if(location.day !== undefined){
  let date_used;
  for(var i = 0; i < values.length; i++ ){
  
    if(values[i].day === location.day){
      date_used = values[i].main_data;
      break;
    }
  }
  history.push({
    pathname:  '/truckactivitypage',
    state : {
      day : location.day, 
      date : date_used,
      reg : location.state,
      manager : location.manager,
      batchout : location.batchout,
      timestamp : location.timestamp,
      estimatedepart : location.estimatedepart,
      tdays : location.totaldays

    }
    
  })
}

  let n = 5
  let  result = new Array(Math.ceil(values.length / n))
.fill()
.map(_ => values.splice(0, n))

    return (
          <>
     
            <Container className="my-5 py-5 bg-dark">
             <div className="content1">
             {result.map((elem,index)=>{

               let style1;
               if(index%2 === 0){
                 style1={
                   alignItems: "flex-left",
                 }
               }
                 else{
                 style1={
                   alignItems:"flex-right",
                 }
                 }
               return (
                  <>
                  <div key={index} style={style1} className="row1">
                  {elem.map((el,ind)=>{
              
                    return (
                      <>

                   <div onClick={()=>{
                     treg = props.reg
                     tdate = el.main_data.toISOString()
                     tday = el.day
                     let totaldays = 0 
                     if(localStorage.getItem('vehicletype') === "T90") totaldays = 56
                     else if(localStorage.getItem('vehicletype') === "T72") totaldays = 54
                     else totaldays = 48
                     history.push({
                      pathname:  `/truckactivitypage/${window.scrollY}`,
                      state : {
                        day : tday, 
                        date : tdate,
                        reg : treg,
                        manager : props.manager,
                        batchout : props.batchout,
                        timestamp : props.timestamp,
                        estimatedepart : props.estimatedepart,
                        tdays : totaldays
    
                      }
                      
                    })


                   }} className={`item bg-${el.status} ${el.status}`} style={{backgroundColor:el.status}}>{el.day}</div>  

                    {el !== elem[elem.length-1]?(<div className="horizontal-seperator"></div>):null}
                    </>
                    )
                  })}
        </div>
        <div className="vertical-seperator-row1">
          {index !== result.length - 1?<div className="vertical-seperator-element"></div>:null}
        </div>
                  </>
               )
             })}
  
      </div>
      </Container>
          </>
    )
}

export default ZigZagTimeLine;