import {Modal,Button,Spinner} from 'react-bootstrap';
import axios from 'axios';
import { useEffect, useState } from 'react';
import deepClone from 'deep-clone'


let truckData = []
const PendingTaskModal = (props)=>{
    const [data,setData] = useState(null)
  


    useEffect(()=>{
      setData(null)

        var config = {
            method: 'get',
            url: `http://localhost:8000/api/truck/${props.reg}`,
            headers: { 
              'Content-Type': 'application/json'
            },
          };
          
          axios(config)
          .then(function (response) {
                truckData.length = 0 
              var j = 0;
              for(var i = 1; i <= 56 ; i ++){
                let activity_list = []
            

                while(j < response.data.items.length ){
                  if(response.data.items[j].itemdesc  !== undefined && response.data.items[j].itemdesc.day ===i)
                  activity_list.push(response.data.items[j++])
                  else if(response.data.items[j].day !== undefined && response.data.items[j].day === i)
                  activity_list.push(response.data.items[j++])
                  else
                  break

                }             
                truckData.push(deepClone(activity_list));
              }
             
              setData(truckData)
          })
          .catch(function (error) {
            console.log(error);
          });
          

    },[props.reg,props.date]) 

    const handleClose = ()=>props.module(false);
    return (
        <>
        
      <Modal show={props.show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title><p className="fw-bold">View Pending Tasks</p></Modal.Title>
        </Modal.Header>
            
            <Modal.Body>{data === null?<>
            <Spinner className="mx-5 " animation="grow" variant="success" />

            </>:(<>{data.map((elem,index)=>{
              return (
                <>
                {elem.filter((elem)=>{
                  let deadline = new Date(Date.parse(elem.deadline))                  
                  return !elem.completed && deadline < new Date()
                }).length !== 0?( 
                  <>
                                  <h2 className="fw-bold">Day {index + 1}</h2>

                  {elem.filter((elem)=>{
              let deadline = new Date(Date.parse(elem.deadline))                  
                    return !elem.completed && deadline < new Date()
                }).map((el,index)=>{
                  return (
                    <>
                    <p>{index + 1}. {el.hasOwnProperty("itemdesc")?el.itemdesc.activity: el.activity } </p>
                    </>
                  )
                }
                )} </>):null}
                </>
              )
            })}</>)                
            }</Modal.Body>

        <Modal.Footer>
          <Button variant="secondary" onClick={()=>{
            handleClose()}}>
            Close
          </Button>
        </Modal.Footer>
      </Modal>

        </>
    )
}

export default PendingTaskModal;