import {Container,Table,Button,Spinner} from 'react-bootstrap';
import { useEffect,useState } from 'react';
import axios from 'axios'
import jsPDF from 'jspdf'; 
import 'jspdf-autotable';



function generate(temp,tank) {  

    const unit = "pt";
    const size = "A4"; // Use A1, A2, A3 or A4
    const orientation = "portrait"; // portrait or landscape

    const marginLeft = 40;
    const doc = new jsPDF(orientation, unit, size);

    doc.setFontSize(15);

    const title = `Tank Inventory Report (Life Item) for Tank BA No: ${tank}`;
    const headers = [["S No", "Updated By","Item","Lifting Norms","Fitted (Yes/No)","Remarks","TimeStamp"]];

    const data = temp.map((elem,index)=> {
    let remarks = "",fitted = "",item=""
    try{remarks = elem.info.split('remarks:')[1].split('for')[0].trim()}catch(e){}
    try{fitted=elem.info.split('fitted: ')[1].split(RegExp(',|for'))[0]}catch(e){}
    try{item=elem.info.split('for')[1]}catch(e){}
    if(remarks === "None") remarks = ""
    let liftingnorms = ""
    if(elem.hrs !== null) liftingnorms += `${elem.hrs} hrs, `
    if(elem.kms !== null) liftingnorms += `${elem.kms} kms, `
    if(elem.cycles !== null) liftingnorms += `${elem.cycles} cycles, `
    if(elem.efcs !== null)  liftingnorms += `${elem.efcs} efcs, `
    if(elem.operations !== null) liftingnorms += `${elem.operations} operations, `
    if(elem.switchings !== null) liftingnorms += `${elem.switchings} switchings, `
    if(elem.yrs !== null) liftingnorms += `${elem.yrs} yrs, ` 
    fitted = (fitted==" yes" || fitted==" Yes")?"Yes":"No"
      
      return [index+1, elem.user,item,liftingnorms,fitted,remarks,elem.timestamp.split(',')[0]]
    
    });

    let content = {
      startY: 50,
      head: headers,
      body: data,
      theme : "grid",
      styles : {
        halign : "left",
      },
      bodyStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center',
      },
      headStyles: {
        lineWidth: 1,
        lineColor: 10,
        valign: "middle",
        halign: 'center'
      },
    };

    doc.text(title, marginLeft, 40);
    doc.autoTable(content);
    doc.save("report.pdf")
}  



const LifeItemReport = (props)=>{

    const [data,setData] = useState(null)

    useEffect(()=>{
        var config = {
        method: 'get',
        url: `http://localhost:8000/api/fetchlogswithparameters/${props.reg}`,
        headers: { 
            'Content-Type': 'application/json'
        },
        };

        axios(config)
        .then(function (response) {
          console.log(response.data)
            setData(response.data)
        })
        .catch(function (error) {
        console.log(error);
        });
// eslint-disable-next-line
    },[])

    return (
        <>
        <Container>
            <h3 className="fw-bold">Could do Items with Life</h3>
            {data!== null ?(
            <>
            <Container>
            <Table responsive striped bordered variant="dark">
  <thead>
    <tr>
      <th>S No</th>
      <th>Updated By </th>
      <th>Item </th>
      <th>Lifting Norms</th>
      <th>Fitted (Yes/No)</th>
      <th>Remarks</th>
      <th>TimeStamp</th>
    </tr>
  </thead>
  <tbody>
  {data.map((elem,index)=>{
       let remarks = "",fitted = "",item=""
       try{remarks = elem.info.split('remarks:')[1].split('for')[0].trim()}catch(e){}
       try{fitted=elem.info.split('fitted: ')[1].split(RegExp(',|for'))[0]}catch(e){}
      try{item=elem.info.split('for')[1]}catch(e){}
      if(remarks === "None") remarks = ""
      let liftingnorms = ""
      if(elem.hrs !== null) liftingnorms += `${elem.hrs} hrs, `
      if(elem.kms !== null) liftingnorms += `${elem.kms} kms, `
      if(elem.cycles !== null) liftingnorms += `${elem.cycles} cycles, `
      if(elem.efcs !== null)  liftingnorms += `${elem.efcs} efcs, `
      if(elem.operations !== null) liftingnorms += `${elem.operations} operations, `
      if(elem.switchings !== null) liftingnorms += `${elem.switchings} switchings, `
      if(elem.yrs !== null) liftingnorms += `${elem.yrs} yrs, ` 
      fitted = (fitted==" yes" || fitted==" Yes")?"Yes":"No"
       return (
    <tr key={index}>
      <td>{index+1}</td>
      <td>{elem.user}</td>
      <td>{item}</td>
      <td>{liftingnorms}</td>
      <td>{fitted}</td>
      <td>{remarks}</td>
      <td>{elem.timestamp.split(',')[0]}</td>
    </tr>
    )
  })}
   
  
  </tbody>
</Table>
<Button className="mx-5 my-5" onClick={()=>{
    generate(data,props.reg)
}}
>Click to Generate Report</Button>
</Container>
</>):<Spinner animation="border" role="status">
    <span className="visually-hidden">Loading...</span>
    </Spinner>}
        </Container>
        
        </>
    )
}

export default LifeItemReport;

