import {Button,Modal,Table,Form} from 'react-bootstrap'; 
import {Trash} from 'react-bootstrap-icons'
import {useState} from 'react';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import DeleteArrivalTruck from './DeleteArrivalTruck';
let dataOptions={
    'BMP':'BMP-I/II',
    'T90':'T-90',
    'T72':'T-72'

}
function convertDate(inputFormat) {
    if(inputFormat==null){
        return('');
    }
    function pad(s) { return (s < 10) ? '0' + s : s; }
    var d = new Date(inputFormat)
    return [pad(d.getDate()), pad(d.getMonth()+1), d.getFullYear()].join('/')
  }
function generate(temp) {  

    const unit = "pt";
    const size = "A3"; // Use A1, A2, A3 or A4
    const orientation = "portrait"; // portrait or landscape
  
    const marginLeft = 250;
    const doc = new jsPDF(orientation, unit, size);
    doc.setFont(undefined, 'bold')

    doc.setFontSize(15);

    const title = `New Arrivals`;
    const headers = [["S No","Eqpt Type","Tank BA No","Unit"]];

    const data =  temp.filter((elem)=>{
        return elem;
      }).sort(function(a,b){
        let a1 = 10000000000, b1 = 10000000000;
        if(a.target !== null) a1 = a.target;
        if(b.target !== null) b1 = b.target;
        return a1 - b1;
     }).map((elem,index)=>{
        return(
            [
                index+1,
                dataOptions[elem.type],
                elem.reg,
                elem.unit,
            ]
            )
            
            
    });
    // console.log("hello");
    // console.log(data)
    let content = {
        startY: 50,
        margin : {left : 160},
        head: headers,
        body: data,
        theme : "grid",
        styles : {
          halign : "left",
        },
        bodyStyles: {
          lineWidth: 1,
          lineColor: 10,
          valign: "middle",
          halign: 'center'
        },
        headStyles: {
          lineWidth: 1,
          lineColor: 10,
          valign: "middle",
          halign: 'center'
        },
        columnStyles: {
        0: {cellWidth: 90},
        1: {cellWidth: 150},
        2: {cellWidth: 150},
        3: {cellWidth: 150},
        4: {cellWidth: 150},
        5: {cellWidth: 150},
        }
        
      };
    doc.text(title, doc.internal.pageSize.getWidth()/2, 30, { align: "center" });
    doc.autoTable(content);
    doc.save("inventoryreport.pdf")
}
