
import React from 'react'
  
const Progress_bar = ({bgcolor,progress,label,height}) => {
    const Parentdiv = {
        height: height,
        width: '100%',
        backgroundColor: 'whitesmoke',
        borderRadius: 30,
        margin: 10,
      }
      
      const Childdiv = {
        height: '100%',
        width: `${progress}%`,
        // backgroundColor: bgcolor,
       borderRadius:30,
        textAlign: 'center',
        backgroundColor: bgcolor === "green"?'#3ba171':""
      }
      
      const progresstext = {
        padding: 5,
        color: 'black',
        fontWeight: 900,
        
      }
        
    return (
    <div style={Parentdiv}>
      <div style={Childdiv} className={bgcolor === "green"?"":bgcolor}>
        <span style={progresstext}>{`${label}`}</span>
      </div>
    </div>
    )
}
  
export default Progress_bar;