import {Container,Table,Button,Spinner} from 'react-bootstrap';
import AddHolidayModal from '../components/AddHolidayModal';
import { useState,useEffect} from 'react';
import axios from 'axios';

const HolidayList = ()=>{


    const [show,setShow] = useState(false);
    const [data,setData] = useState(null);
    const [load,setLoad] = useState(false)
    useEffect(()=>{
      var config = {
        method: 'get',
        url: 'http://localhost:8000/api/holiday',
        headers: { 
          'Content-Type': 'application/json'
        },

      };
      
      axios(config)
      .then(function (response) {
        setData(response.data)
        setLoad(false)
      })
      .catch(function (error) {
        console.log(error);
      });
    },[load])
    return (
        <>

        {localStorage.getItem('id') === null ? (

            <h1> Pls Login Before you Continue</h1>
        ) : (

            <>

            <AddHolidayModal 
            module = {setShow}
            show={show}
            module1={setLoad}
        />
        <Container className="bg-dark text-light my-5 mx-5 py-2">
        <h1 className="fw-bold mx-5"> Non Working Day/Holiday List</h1>
        <Button onClick={()=>{
            setShow(true)
        }} className="my-2 mx-5">
            Add New Holiday Date
        </Button>
        </Container>

        <Container>
        {data !== null? (
          <Table responsive striped bordered hover variant="dark">
  <thead>
    <tr>
      <th>S No.</th>
      <th>Holiday </th>
      <th>Date</th>
    </tr>
  </thead>
  <tbody>
  {data.map((elem,index)=>{
    return (
      <tr>
      <td>{index + 1}</td>
      <td>{elem.name}</td>
      <td>{new Date(Date.parse(elem.date)).toDateString()}</td>
    </tr>
    )
  })}  
  </tbody>
</Table>
        ) : (
          <Spinner animation="border" variant="success" />

        )}
      
        </Container>
            </>


        )}


       
        </>
    )
}

export default HolidayList;