function generate(temp,tank,isCompleted) {  

  const unit = "pt";
  const size = "A3"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);

  doc.setFontSize(15);

  const title = `                                       Life Item Inventory Report For Tank (${ localStorage.getItem('vehicletype') === "T72" ? "T-72" : (localStorage.getItem('vehicletype') === "T90" ? "T-90" : "BMP-II") }) BA No. : ${tank}`;
  const headers = [["S No.", "Nomenclature","Lifting Norms",
  "Fitted (Yes/No)","Remarks"]];

  const data = temp.filter((elem)=>{
    return elem.fitted === (isCompleted?"yes":"no")
  }).map((elem,index)=> {
    let liftingnorms = ""
    if(elem.item.hrs !== null) liftingnorms += `${elem.item.hrs} hrs, `
    if(elem.item.kms !== null) liftingnorms += `${elem.item.kms} kms, `
    if(elem.item.cycles !== null) liftingnorms += `${elem.item.cycles} cycles, `
    if(elem.item.efcs !== null)  liftingnorms += `${elem.item.efcs} efcs, `
    if(elem.item.operations !== null) liftingnorms += `${elem.item.operations} operations, `
    if(elem.item.switchings !== null) liftingnorms += `${elem.item.switchings} switchings, `
    if(elem.item.yrs !== null) liftingnorms += `${elem.item.yrs} yrs, ` 
    return [index + 1,elem.item.nomenclature,liftingnorms,(elem.fitted)==="no"?"No":"Yes",
    elem.remarks]});

  let content = {
    startY: 50,
    head: headers,
    body: data,
    theme : "grid",
    styles : {
      halign : "left",
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    },
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
  };

  doc.text(title, marginLeft, 40);
  doc.autoTable(content);
  doc.save("inventoryreport.pdf")
}  

function generate1(temp,tank) {  


  
  let check = []
  temp.filter((elem)=>{
    return elem.fitted === "yes"
  }).forEach((elem)=> check.push(elem))
  temp.filter((elem)=>{
    return elem.fitted === "no"
  }).forEach((elem)=> check.push(elem))

  const unit = "pt";
  const size = "A3"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);
  // doc.setFont(undefined, 'bold')

  doc.setFontSize(15);

  const title = `                                       Life Item Inventory Report for Tank (${ localStorage.getItem('vehicletype') === "T72" ? "T-72" : (localStorage.getItem('vehicletype') === "T90" ? "T-90" : "BMP-II") }) with BA No. : ${tank}`;
  const headers = [["S No.", "Nomenclature","Lifting Norms",
  "Fitted (Yes/No)","Remarks"]];
  let yes=0,no=0,na=0;
  
  temp.forEach((elem)=>{
    if(elem.fitted === "yes") yes ++;
    else no++;
  })

  const data = check.map((elem,index)=> {
    let liftingnorms = ""
    if(elem.item.hrs !== null) liftingnorms += `${elem.item.hrs} hrs, `
    if(elem.item.kms !== null) liftingnorms += `${elem.item.kms} kms, `
    if(elem.item.cycles !== null) liftingnorms += `${elem.item.cycles} cycles, `
    if(elem.item.efcs !== null)  liftingnorms += `${elem.item.efcs} efcs, `
    if(elem.item.operations !== null) liftingnorms += `${elem.item.operations} operations, `
    if(elem.item.switchings !== null) liftingnorms += `${elem.item.switchings} switchings, `
    if(elem.item.yrs !== null) liftingnorms += `${elem.item.yrs} yrs, ` 
    
    
    return [index + 1,elem.item.nomenclature,liftingnorms,(elem.fitted)==="yes"?"Yes":"No",
    elem.remarks]}
    
    );

  let content = {
    startY: 50,
    head: headers,
    body: data,
    theme : "grid",
    styles : {
      halign : "center",
      // fontStyle : 'bold'
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    },
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
  };

  doc.text(title, marginLeft, 40);
  doc.autoTable(content); doc.autoTable({
    head: [["Yes","No"]],
    body: [[yes,no,na]],
});  
  doc.save("inventoryreport.pdf")
}  





