import {Container,Table,Spinner,Button} from 'react-bootstrap';
import {useEffect,useState} from 'react';
import axios from 'axios';
import jsPDF from 'jspdf'; 
import 'jspdf-autotable';

function convertDate(inputFormat) {
  function pad(s) { return (s < 10) ? '0' + s : s; }
  var d = new Date(inputFormat)
  return [pad(d.getDate()), pad(d.getMonth()+1), d.getFullYear()].join('/')
}

function generate(temp,user) {  

  const unit = "pt";
  const size = "A3"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);
  doc.setFont(undefined, 'bold')

  doc.setFontSize(15);

  const title = `Could Do Report for user : ${user}`;
  const headers = [["S No.", "Tank BA No.","MS No","Part Number","Nomenclature","VED",
  "AU","Auth for 01 Tks","Fitted (Yes/No)","Issued from Ord","Issued from LP","Date","Remarks","TimeStamp"]];

  const data = temp.map((elem,index)=> {
    let fitted="",remarks="",issuedfromexord="",issuedfromlp="",date=""
    try{fitted=elem.info.split('fitted')[1].split(',')[0]}catch(e){}
    try{remarks=elem.info.split('remarks')[1].split(':')[1].split('for')[0].trim()}catch(e){}
    try{issuedfromexord=elem.info.split('issuedfromexord')[1].split(':')[1].split(',')[0]}catch(e){}
    try{issuedfromlp=elem.info.split("issuedfromlp")[1].split(":")[1].split(",")[0]}catch(e){}
    try{date = elem.info.split("date :")[1].trim()}catch(e){}
    if(remarks === "None") remarks = ""
    if(date === "None") date = "-"



    return [index+1, elem.truck,
      elem.msno,
      elem.partno,
      elem.item,
      elem.ved,
      elem.au, 
      elem.authfor01tks,
      fitted,issuedfromexord,issuedfromlp,date,remarks,
      convertDate(elem.timestamp.split(',')[0])]
  
  });

  let content = {
    startY: 50,
    margin : {left : 10},

    head: headers,
    body: data,
    theme : "grid",
    styles : {
      halign : "left",
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    },
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
    columnStyles: {
      0: {cellWidth: 35},
      1: {cellWidth: 80},
      2: {cellWidth: 30},
      3: {cellWidth: 110},
      4: {cellWidth: 120},
      5: {cellWidth: 30},
      6 : {cellWidth : 35},
      7: {cellWidth: 42},
      8: {cellWidth: 42},
      9: {cellWidth: 44},
      10: {cellWidth: 44},
      11: {cellWidth: 70},
      12: {cellWidth: 70},
      13: {cellWidth: 80},
      
    }
  };

  doc.text(title, marginLeft, 40);
  doc.autoTable(content);
  doc.save("report.pdf")
}  


const UserCouldDoLife = (props)=>{

    const [data,setData] = useState(null)

    useEffect(()=>{

        var data = JSON.stringify({"username":props.id,
      "type" : localStorage.getItem('vehicletype')});

        var config = {
          method: 'post',
          url: 'http://localhost:8000/api/coulddohistory',
          headers: { 
            'Content-Type': 'application/json'
          },
          data : data
        };
        
        axios(config)
        .then(function (response) {
            setData(response.data)
        })
        .catch(function (error) {
          console.log(error);
        });
        
        // eslint-disable-next-line
    },[])


    return (
        <>
        <Container>
        {data !== null? (
            <>
            <Table striped bordered hover variant="dark">
  <thead>
    <tr>
      <th>S No. </th>
      <th>Tank BA No.</th>
      <th>Username</th>
      <th>MS No</th>
      <th>Part Number</th>
      <th>Nomenclature</th>
      <th>VED</th>
      <th>AU</th>
      <th>Auth for 01 Tks</th>
      <th>Fitted (Yes/No)</th>
      <th>Issued from Ord</th>
      <th>Issued from LP</th>
      <th>Date</th>
      <th>Remarks</th>
      <th>Time Stamp</th>
    </tr>
  </thead>
  <tbody>
  {data.map((elem,index)=>{
    let fitted="",remarks="",issuedfromexord="",issuedfromlp="",date= ""
    try{fitted=elem.info.split('fitted')[1].split(',')[0]}catch(e){}
    try{remarks=elem.info.split('remarks')[1].split(':')[1].split('for')[0].trim()}catch(e){}
    try{issuedfromexord=elem.info.split('issuedfromexord')[1].split(':')[1].split(',')[0]}catch(e){}
    try{issuedfromlp=elem.info.split("issuedfromlp")[1].split(":")[1].split(",")[0]}catch(e){}
    try{date = elem.info.split("date :")[1].trim()}catch(e){}
    if(remarks === "None") remarks = ""
    if(date === "None") date = ""
    return (
        <tr>
      <td>{index + 1}</td>
      <td>{elem.truck}</td>
      <td>{props.name}</td>
      <td>{elem.msno}</td>
      <td>{elem.partno}</td>
      <td>{elem.item}</td>
      <td>{elem.ved}</td>
      <td>{elem.au}</td>
      <td>{elem.authfor01tks}</td>
      <td>{fitted}</td>
      <td>{issuedfromexord}</td>
      <td>{issuedfromlp}</td>
      <td>{date}</td>
      <td>{remarks}</td>
      <td>{convertDate(elem.timestamp.split(',')[0])}</td>
    </tr>
      )
  })}
    
    
  </tbody>
</Table>
            </>
        ): (
            <>
            <Spinner animation="border" role="status">
                <span className="visually-hidden">Loading...</span>
                </Spinner>
               </>
        )}
        <Button variant="success" onClick={()=>{
            generate(data,props.name)
          }}>Generate Report</Button>
        </Container>
        </>
    )
}
export default UserCouldDoLife;