import { Modal,Button,Alert,Spinner} from "react-bootstrap";
import axios from 'axios';
import {useState} from 'react';
const AddHolidayModal = (props)=>{
    
    const handleClose = ()=>props.module(false);
    const [alert,showAlert] = useState(false);
    const[loading, setLoading] = useState(false);
    let name=null,date = null
    
    return (
        <>
 <Modal show={props.show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>Add New Date</Modal.Title>
        </Modal.Header>
        <Modal.Body>
        {alert?( <Alert variant="danger">
      Information Missing!!
  </Alert>) :null}
      
             <label for="date">Date:{' '}</label>
  <input onChange={(e)=>date = e.target.value} type="date" id="date" name="date"/>

      <br/>
      <br/>
  <label for="holiday">Holiday:{' '}</label>
  <input onChange={(e)=>name = e.target.value} type="text" id="holiday" name="holiday"/>

        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleClose}>
            Close
          </Button>
          <Button variant="primary" onClick={()=>{
            let new_date = new Date(Date.parse(date))
              new_date.setHours(new_date.getHours() + 6)

            if(name === null || date === null){
              showAlert(true)
            }
            else{
              setLoading(true)
             var data = JSON.stringify({"name":name,"holidaydate":new_date});
        var config = {
          method: 'post',
          url: 'http://localhost:8000/api/holiday',
          headers: { 
            'Content-Type': 'application/json'
          },
          data : data
        };

        axios(config)
        .then(function (response) {
          handleClose()
          props.module1(true)
          setLoading(false)

        })
        .catch(function (error) {
          console.log(error);
        });
        showAlert(false)

          }
          }}>
            Save Changes
          </Button>
          {loading?<Spinner animation="border" role="status">
  <span className="visually-hidden">Loading...</span>
</Spinner>:null}
        </Modal.Footer>
      </Modal>
        </>
    )
}

export default AddHolidayModal;