function find_session(curr_date){
    let parseDate = new Date(curr_date)
    // console.log("dates are:")
    // console.log(parseDate);
    let date = parseDate.getDate()
    let month = parseDate.getMonth() + 1;
    let year = parseDate.getFullYear();
    
    let new1 = new Date(2011, month, date)
    let new2 = new Date(2011, 3, 1);
    let prevYear, nextYear;
    if(new1 >= new2){
        prevYear = year;
        nextYear = prevYear + 1;
    }else{
      prevYear = year - 1;
      nextYear = prevYear + 1;
    }
    return prevYear.toString() + '-' + nextYear.toString().substr(2, 3);

}


function formatDate(curr_date){
  if(curr_date === null) return ""
  let new_date = new Date(curr_date)
  function pad(s){return (s < 10) ? '0' + s : s}
  return pad(new_date.getDate()) + '-' + pad(new_date.getMonth() + 1) + '-' + pad(new_date.getFullYear())
}

function findValue(arrival, required_days){

  let value = (Math.round((new Date()-Date.parse(arrival))/(1000*60*60*24))/required_days)*100
  if(value <= 0) return 0;
  if(value >= 100) return 100;
  return value 

}



