import {Container,Table,Spinner,Button} from 'react-bootstrap';
import {useEffect,useState} from 'react';
import axios from 'axios';
import jsPDF from 'jspdf'; 
import 'jspdf-autotable';

function convertDate(inputFormat) {
  function pad(s) { return (s < 10) ? '0' + s : s; }
  var d = new Date(inputFormat)
  return [pad(d.getDate()), pad(d.getMonth()+1), d.getFullYear()].join('/')
}

function generate(temp,user) {  

  const unit = "pt";
  const size = "A4"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);
  doc.setFont(undefined, 'bold')

  doc.setFontSize(15);

  const title = `User Expendable Report for User : ${user}`;
  const headers = [["S No.", "Tank BA No.","Username","Item","AU","Auth for 01 Tks","Fitted (Yes/No)","Part Number","Issued from Ord","Issued from LP","Time Stamp"]];

  const data = temp.map((elem,index)=> {
    let fitted = "",partnumber = "",issuedfromexord="",issuedfromlp=""
    try{fitted=elem.info.split('fitted')[1].split(',')[0]}catch(e){}
    try{partnumber=elem.info.split('for')[1].split(',')[0]}catch(e){}
    try{issuedfromexord=elem.info.split('issuedfromexord: ')[1].split(', issuedfromlp')[0]}catch(e){}
    try{issuedfromlp=elem.info.split('issuedfromlp')[1].split(':')[1].split(',')[0]}catch(e){}

    return [index+1, 
    elem.truck,
    user,
    elem.item,
    elem.au, 
    elem.auth01tks,
    fitted,
      partnumber,
      issuedfromexord,
      issuedfromlp,
      convertDate(elem.timestamp.split(',')[0])];
    });
  
  let content = {
    startY: 50,
    head: headers,
    body: data,
    theme : "grid",
    styles : {
      halign : "left",
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    },
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
  };

  doc.text(title, marginLeft, 40);
  doc.autoTable(content);
  doc.save("report.pdf")
}  

const UserExpendablesReport = (props)=>{

    const [data,setData] = useState(null)

    useEffect(()=>{

        var data = JSON.stringify({"username":props.id,
      "type":localStorage.getItem('vehicletype')});

        var config = {
          method: 'post',
          url: 'http://localhost:8000/api/userexpendableitemhistory',
          headers: { 
            'Content-Type': 'application/json'
          },
          data : data
        };
        
        axios(config)
        .then(function (response) {
            setData(response.data)
        })
        .catch(function (error) {
          console.log(error);
        });
        
        // eslint-disable-next-line
    },[])


    return (
        <>
        <Container>
        {data !== null? (
            <>
            <Table striped bordered hover variant="dark">
  <thead>
    <tr>
      <th>S No. </th>
      <th>Tank BA No.</th>
      <th>Username</th>
      <th>Item</th>
      <th>AU</th>
      <th>Auth for 01 Tks</th>
      <th>Fitted (Yes/No)</th>
      <th>Part Number</th>
      <th>Issued From Ord</th>
      <th>Issued From LP</th>
      <th>Time Stamp</th>
    </tr>
  </thead>
  <tbody>
  {data.map((elem,index)=>{

    let fitted = "",partnumber = "",issuedfromexord="",issuedfromlp=""
    try{fitted=elem.info.split('fitted')[1].split(',')[0]}catch(e){}
    try{partnumber=elem.info.split('for')[1].split(',')[0]}catch(e){}
    try{issuedfromexord=elem.info.split('issuedfromexord: ')[1].split(', issuedfromlp')[0]}catch(e){}
    try{issuedfromlp=elem.info.split('issuedfromlp')[1].split(':')[1].split(',')[0]}catch(e){}

      return (
        <tr>
      <td>{index + 1}</td>
      <td>{elem.truck}</td>
      <td>{props.name}</td>
      <td>{elem.item}</td>
      <td>{elem.au}</td>
      <td>{elem.auth01tks}</td>
      <td>{fitted}</td>
      <td>{partnumber}</td>
      <td>{issuedfromexord}</td>
      <td>{issuedfromlp}</td>
      <td>{convertDate(elem.timestamp.split(',')[0])}</td>
    </tr>
      )
  })}
    
    
  </tbody>
</Table>
            </>
        ): (
            <>
            <Spinner animation="border" role="status">
                <span className="visually-hidden">Loading...</span>
                </Spinner>
               </>
        )}
        <Button variant="success" onClick={()=>{
          generate(data,props.name)
        }}>Generate Report</Button>
       
        </Container>
        </>
    )
}

export default UserExpendablesReport;