import {Modal,Button,Form} from 'react-bootstrap';
import axios from 'axios';

let day=""
let activity=""
let critical = false
let noofteck=""
let truckid =""
let time=""
let deadline=""

const AddTaskModal = (props)=>{
  deadline = props.deadline 
  truckid = props.reg
  day = props.day 
  
    
    const handleClose = ()=>props.module(false);
    return (
    <>
       <Modal show={props.show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>Add New Task</Modal.Title>
        </Modal.Header>
        <Modal.Body>
        <Form>
  <Form.Group className="mb-3" controlId="formBasicEmail">
    <Form.Label>Name of the Task</Form.Label>
    <Form.Control onChange={(e)=>activity = e.target.value} type="text" placeholder="Enter Activity Description" />
  </Form.Group>
  
  <Form.Group className="mb-3" controlId="formBasicEmail">
    <Form.Label>Time</Form.Label>
    <Form.Control onChange={(e)=>time = e.target.value} type="text" placeholder="For Eg : 30 min /1 Hr" />
  </Form.Group>

  <Form.Group className="mb-3" controlId="formBasicEmail">
    <Form.Label>Man Power Required</Form.Label>
    <Form.Control onChange={(e)=>noofteck = e.target.value} type="text" placeholder="Eg : 01xTech" />
  </Form.Group>
</Form>

        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleClose}>
            Close
          </Button>
          <Button variant="primary" onClick={()=>{
            deadline.setHours(deadline.getHours() + 6)
                 var data = JSON.stringify({
              "username" : atob(localStorage.getItem("id")),
              "critical":critical,
              "deadline":deadline,
              "noofteck":noofteck,
              "activity":activity,
              "time":time,
              "day":day});

            var config = {
              method: 'post',
              url:`http://localhost:8000/api/truck/${truckid}`,
              headers: { 
                'Content-Type': 'application/json'
              },
              data : data
            };

            axios(config)
            .then(function (response) {
              props.module2(true)
            })
            .catch(function (error) {
              console.log(error);
            });

            handleClose()}}>
            Save Changes
          </Button>
        </Modal.Footer>
      </Modal>
    
    </>)
}

export default AddTaskModal;