import {Container,Form,Button,Nav} from 'react-bootstrap';
import axios from 'axios';
import {useState,useEffect} from 'react';
import ActivityReport from '../components/ActivityReport';
import CouldDoReport from '../components/CouldDoReport';
import LifeItemReport from '../components/LifeItemReport';
import MustDoReport from '../components/MustDoReport'
import RotablesReport from '../components/RotablesReport';
import {useHistory, useLocation} from 'react-router-dom';
import ExpendablesReport from '../components/ExpendablesReport';
import DelayReport from '../components/DelayReport';

let truckIDs = []
let trucksearch = ""

const SearchByID = ()=>{
   
    const [term,setSearchTerm] = useState('')
    const [truck,setTruck] = useState('')
    const[tab,setTab] = useState(1)
    const [truckfrom, settruckfrom] = useState(null)
    let location = useLocation()
    let history = useHistory()

    

  

    useEffect(()=>{
      if(location.state !== undefined)
      {
        setTruck(location.state)
        settruckfrom(location.state)
      }

      truckIDs.length = 0 
      var config = {
        method: 'get',
        // url: `http://localhost:8000/api/trucklist?type=${localStorage.getItem('vehicletype')}`,
        url: `http://localhost:8000/api/alltrucks`,
        headers: { },
      };

      axios(config)
      .then(function (response) {
       for(var i = 0; i < response.data.length ; i ++)
       truckIDs.push(response.data[i].reg)

      })
      .catch(function (error) {
        console.log(error);
      });

    },[])
    
         
   
    return (
        <>
        <Container className="text-dark" style={{
          "backgroundColor" : "#2a6099",
          "textAlign":'center'
        }}>
          <h1 className="my-2 mx-5 fw-bold">{localStorage.getItem('vehicletype') === "BMP"?"BMP-II":(localStorage.getItem('vehicletype') === "T72"?"T-72" : "T-90")} SECTION</h1>
        </Container>
        {truckfrom === null?(
          
            <Container className="bg-dark text-light my-5 py-3">  
            <h1 className="my-2 fw-bold">Search for Tank by BA No.</h1>
            <Form>
            <div className="row">
      <Form.Group className="col-sm-4" controlId="formBasicEmail">
        <Form.Label>Tank BA No. (Start Typing to Search)</Form.Label>
        <Form.Label><p>Note: If you find your desired Tank, click on it to view its report</p></Form.Label>
        <Form.Control type="text" value={term} onChange={(e)=>setSearchTerm(e.target.value)} placeholder="Enter Tank BA No. For eg : T1521212" />
      </Form.Group>
         </div>
            </Form>
           </Container>
    
        ): null}
      

        <Container className="bg-dark py-2 px-2">
        <div className="row my-3">
        
        {truckIDs.filter(
            (val,key)=>{
              if(term === '')
              return false
              
              if(val.toLowerCase().includes(term.toLowerCase()))
              return val;
              
              return false;
            }

        ).map((elem,index)=>{
          return (
            <div key={index} className="col">
            <Button onClick={()=>{
              trucksearch =elem
              setTruck(elem)

            }} className="my-3 mx-3" variant="success">{elem} </Button>
            </div>
          )

        })}
        </div>
        </Container>

        {truck !== ''?(
          <>
          <Container className="bg-dark text-light">
          <h1>Tank BA No. : {location.state !== undefined?location.state : trucksearch} </h1>
          <Button id="btnclose" className='mb-3' onClick={()=>{
            history.push('/maintruckdb')
            window.location.reload()
            }} style={{marginRight:'5px'}} variant="success">Go Back
        </Button>
          <Button
          className="mb-3 mx-auto"
          onClick={()=>{
            setTruck('')
            setSearchTerm('')
            settruckfrom(null)
          }}
          >Click here to search for a new Tank</Button>
          </Container>
          <Container
      className="my-5 bg-warning fw-bold text-dark"
      >
       <Nav variant="tabs" defaultActiveKey={1}>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
    className="text-dark" 
    onClick={()=>{
      setTab(1)
      setSearchTerm('')

    }}
    eventKey={1}>Activity Report </Nav.Link>
  </Nav.Item>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(2)
  }}
       className="text-dark"  eventKey={2}>Must Do Report</Nav.Link>
  </Nav.Item>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(3)
  }}
       className="text-dark"  eventKey={3}>Could Do Report(With Life)</Nav.Link>
  </Nav.Item>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(4)
  }}
       className="text-dark"  eventKey={4}>Could Do Report (Without Life)</Nav.Link>
  </Nav.Item>

  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(5)
  }}
    className="text-dark"  eventKey={5}>Rotables Report</Nav.Link>
  </Nav.Item>

  
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(6)
  }}
    className="text-dark"  eventKey={6}>Expendables Report</Nav.Link>
  </Nav.Item>



  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(7)
  }}
    className="text-dark"  eventKey={7}>Delay Report</Nav.Link>
  </Nav.Item>





 
</Nav>
</Container>
          {tab === 1?<ActivityReport reg={truck}/>:null}
          {tab === 2?<MustDoReport reg={truck}/>:null}
          {tab === 3?<LifeItemReport reg={truck}/>:null}
          {tab === 4?<CouldDoReport reg={truck}/>:null}
          {tab === 5?<RotablesReport reg={truck}/>:null}
          {tab === 6?<ExpendablesReport reg={truck}/> : null}
          {tab === 7?<DelayReport reg={truck}/> : null}

          </>
        ):null}
       
        </>
    )

}

export default SearchByID;