let deadline =""
let day=""
let disable_tick = false

function find_difference(firstDate,secondDate,holidaylist){

  const oneDay = 24 * 60 * 60 * 1000; 
  const diffDays = Math.round((firstDate - secondDate) / oneDay);
  var count = 0
 
  for (var i = 0; i < holidaylist.length; i ++ ){
    let date = new Date(holidaylist[i])
    if(date >= secondDate && date <= firstDate){
      count ++
    }
  }

  return diffDays - count
}

let delay = 0


