import {Button,Modal,Table,Form} from 'react-bootstrap'; 
import axios from 'axios';
import {useEffect, useState} from 'react';

async function getNewArrivalCount(){
    let res;
    try{
      res = await axios.get(`http://localhost:8000/api/getnewarrival`)
      let ans = res.data
        return ans
      }catch(error){
        return "error"
      }
  }

  const ChangeCountModal = (props)=>{
      const [miss,setMiss] = useState(false);
      const [exists, setExists] = useState(false);
      const handleClose = () => props.module(false);
      let countData = props.counData
      let temp = countData[0]
      let variant;
      if (props.variant) {
        variant = props.variant;
      }
      console.log(temp)
      if(countData.length!==0){
          console.log(temp.BMPcount)
      }
      
    return (
        <>

        <Modal show={props.show} onHide={handleClose}>
          <Modal.Header closeButton>
            <Modal.Title><p className="fw-bold">{variant===1 ? "Update New Arrival Count" : "Update Target"}</p></Modal.Title>
          </Modal.Header>
          <Modal.Body>
          <Table className="mx-auto w-auto text-center" striped bordered hover variant="dark" responsive>
                <thead>
                    <tr>
                    <th className='col-3'>Veh Type</th>
                    <th className='col-2'>{variant===1 ? "Count" : "Target"}</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td>TK-90</td>
                        <td> 
                             {variant===1 && <Form.Control defaultValue={(temp)?parseInt(temp.T90count):"0"} onChange={(e)=>(countData)?countData[0].T90count= e.target.value:"0"} type='number'/>}

                             {variant===2 && <Form.Control defaultValue={(countData[0])?parseInt(countData[0].T90Tgtcount):"0"} onChange={(e)=>(countData)?countData[0].T90Tgtcount= e.target.value:"0"} type='number'/>}
                             </td>
                    </tr>
                    <tr>
                        <td>TK-72</td>
                        <td> 
                             {variant===1 && <Form.Control defaultValue={(temp)?parseInt(temp.T72count):"0"} onChange={(e)=>(countData)?countData[0].T72count = e.target.value:"0"} type='number'/>}

                             {variant===2 && <Form.Control defaultValue={(countData[0])?parseInt(countData[0].T72Tgtcount):"0"} onChange={(e)=>(countData)?countData[0].T72Tgtcount = e.target.value:"0"} type='number'/>}
                             </td>
                    </tr>
                    <tr>
                        <td>BMP-I/II</td>
                        <td> 
                             {variant===1 && <Form.Control defaultValue={(temp)?parseInt(temp.BMPcount):"0"} onChange={(e)=>(countData)?countData[0].BMPcount = e.target.value:"0"} type='number'/>}

                             {variant===2 && <Form.Control defaultValue={(countData[0])?parseInt(countData[0].BMPTgtcount):"0"} onChange={(e)=>(countData)?countData[0].BMPTgtcount = e.target.value:"0"} type='number'/>}
                             </td>
                    </tr>
                </tbody>
          </Table>       

          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={handleClose}>
              Close
            </Button>
            <Button type="submit" variant="primary" onClick={()=>{
                handleClose()
                var data1;
                if (variant === 1) {
                  data1 = JSON.stringify({"T72count": parseInt(countData[0].T72count),
                  "T90count": parseInt(countData[0].T90count),
                  "BMPcount": parseInt(countData[0].BMPcount)
                   });
                }
                else {
                  data1 = JSON.stringify({"T72TgtCount": parseInt(countData[0].T72Tgtcount),
                  "T90TgtCount": parseInt(countData[0].T90Tgtcount),
                  "BMPTgtCount": parseInt(countData[0].BMPTgtcount)
                   });
                }
              var config = {
              method: 'put',
              url: (variant === 1 ? `http://localhost:8000/api/getnewarrival` : `http://localhost:8000/api/gettgt`),
              headers: { 
                'Content-Type': 'application/json'
              },
              data : data1
            };

            axios(config)
            .then(function (response) {
            })
            .catch(function (error) {
              console.log(error);
            });
            }}>
            Submit 
            </Button>
          </Modal.Footer>
        </Modal>
      </>
    )
}




export default ChangeCountModal;