import {Container,Form,Button,Nav} from 'react-bootstrap';
import axios from 'axios';
import {useState,useEffect} from 'react';
import ActivityReport from '../components/ActivityReport';
import CouldDoReport from '../components/CouldDoReport';
import LifeItemReport from '../components/LifeItemReport';
import MustDoReport from '../components/MustDoReport'
import RotablesReport from '../components/RotablesReport';


let truckIDs = []
let unitsearch = ""
let trucksearch = ""


const SearchByUnit = ()=>{
   
    const [term,setSearchTerm] = useState('')
    // eslint-disable-next-line
    const [truck,setTruck] = useState('')
    const[tab,setTab] = useState(1)
    const [list,showList] = useState(false)
    const [listdata,setlistdata] = useState(null)
    const [search,setSearch] = useState(false)

    useEffect(()=>{

      truckIDs.length = 0 
      var config = {
        method: 'get',
        url: `http://localhost:8000/api/trucklist?type=${localStorage.getItem('vehicletype')}`,
        headers: { },
      };

      axios(config)
      .then(function (response) {
       for(var i = 0; i < response.data.length ; i ++)
       if(response.data[i].unit !== null)
       truckIDs.push(response.data[i].unit)

      })
      .catch(function (error) {
        console.log(error);
      });

    },[])
    
         
   
    return (
        <>
        <Container className="bg-dark text-light my-5 py-3">  
        <h1 className="my-2 fw-bold">Search by Tank Unit</h1>
        

        <Form>
        <div className="row">
  <Form.Group className="col-sm-4" controlId="formBasicEmail">
    <Form.Label>Tank Unit (Start Typing to Search)</Form.Label>
    <Form.Label><p>Note: If you find your desired Tank, click on it to view its report</p></Form.Label>
    <Form.Control type="text" value={term} onChange={(e)=>setSearchTerm(e.target.value)} placeholder="Enter Tank BA No. For eg : T1521212" />
  </Form.Group>
     </div>
        </Form>
       </Container>


        <Container className="bg-dark py-2 px-2">
        <div className="row my-3">
        
        {truckIDs.filter(
            (val,key)=>{
              if(term === "")
              return false;
              else if(val.toLowerCase().includes(term.toLowerCase()))
              return val;
              return false;
            }

        ).map((elem,index)=>{
          return (
            <div key={index} className="col">
            <Button onClick={()=>{
              unitsearch =elem
              setTruck(elem)
              setSearchTerm('')
           
              
              var config = {
                method: 'get',
                url:   `http://localhost:8000/api/searchbyunit/${unitsearch}`,
                headers: { 
                  'Content-Type': 'application/json'
                },
                data : null
              };
              
              axios(config)
              .then(function (response) {
                  setlistdata(response.data)

            })
              .catch(function (error) {
                console.log(error);
              });

                showList(true)

            }} className="my-3 mx-3" variant="success">{elem} </Button>
            </div>
          )

        })}
        </div>
        {list === true && search === false ?(
            <>
            {   
                (listdata !== null) ? (
                    <>
                     <>
                <h1 className="text-light">Show List of Tanks: </h1> 
            <ul>
                {listdata.map((elem)=>{
                    return (
                <li><Button onClick={()=>{
                    trucksearch = elem.regno;
                    setSearch(true)
                }} className="my-2 mx-2">{elem.regno}</Button></li>

                    )
                })}
              

            </ul>
            </>
                    </>
                ): <h1>Loading..</h1>

            }
           </>
        ) : null}

        </Container>

    
        {search === true?(
          <>
          <Container className="bg-dark text-light">
          <h1>Tank BA No. : {trucksearch} </h1>
          <Button
          className="mb-3 mx-auto"
          onClick={()=>{
            setSearch(false)
            showList(false)
          }}
          >Click here to search for a new Tank</Button>
          </Container>
          <Container
      className="my-5 bg-warning fw-bold text-dark"
      >
       <Nav variant="tabs" defaultActiveKey={1}>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
    className="text-dark" 
    onClick={()=>{
      setTab(1)
    }}
    eventKey={1}>Activity Report </Nav.Link>
  </Nav.Item>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(2)
  }}
       className="text-dark"  eventKey={2}>Must Do Report</Nav.Link>
  </Nav.Item>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(3)
  }}
       className="text-dark"  eventKey={3}>Could Do Report(With Life)</Nav.Link>
  </Nav.Item>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(4)
  }}
       className="text-dark"  eventKey={4}>Could Do Report (Without Life)</Nav.Link>
  </Nav.Item>

  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(5)
  }}
    className="text-dark"  eventKey={5}>Rotables Report</Nav.Link>
  </Nav.Item>
 

</Nav>
</Container>
          {tab === 1?<ActivityReport reg={trucksearch}/>:null}
          {tab === 2?<MustDoReport reg={trucksearch}/>:null}
          {tab === 3?<LifeItemReport reg={trucksearch}/>:null}
          {tab === 4?<CouldDoReport reg={trucksearch}/>:null}
          {tab === 5?<RotablesReport reg={trucksearch}/>:null}
        

          </>
        ):null}
       
        </>
    )

}

export default SearchByUnit;