import {Button,Modal,Form} from 'react-bootstrap'; 
import axios from 'axios';
import {useState} from 'react';
window.hours =null 
window.yrs = null
window.kms = null
window.batchoutdate = null
window.fmn = null
window.unit=null
window.reportingdate = null;
window.reg =null
const AddTruckModal = (props)=>{
    const [miss,setMiss] = useState(false);
    const [exists, setExists] = useState(false)
    const handleClose = () => props.module(false);
    return (
        <>

        <Modal show={props.show} onHide={handleClose}>
          <Modal.Header closeButton>
            <Modal.Title><p className="fw-bold">Add New Tank</p></Modal.Title>
          </Modal.Header>
          <Modal.Body>
          {miss?(<p className="text-center" style={{color:"red"}}>Missing Values</p>):null}
          {exists?(<p className="text-center" style={{color:"red"}}>Tank Already Exists</p>):null}
                <Form>
        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Tank BA Number</Form.Label>
            <Form.Control onChange={(e)=>window.reg=e.target.value} type="text" placeholder="For Eg: T54321234" />
        </Form.Group>

        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Target</Form.Label>
            <Form.Control onChange={(e)=>window.target=e.target.value} type="number" placeholder="" />
        </Form.Group>

        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>FMN</Form.Label>
            <Form.Control onChange={(e)=>window.fmn=e.target.value} type="text"  />
        </Form.Group>

        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Unit</Form.Label>
            <Form.Control onChange={(e)=>window.unit=e.target.value} type="text"  />
        </Form.Group>

        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Date In</Form.Label>
            <Form.Control onChange={(e)=>window.reportingdate=e.target.value} type="date"  />
        </Form.Group>


      
        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Distance Travelled (In Km)</Form.Label>
            <Form.Control onChange={(e)=>window.kms=e.target.value} type="number" />
        </Form.Group>


        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Time Spent (In Years)</Form.Label>
            <Form.Control onChange={(e)=>window.yrs=e.target.value} type="number" />
        </Form.Group>




        <Form.Group className="mb-3" controlId="formBasicEmail">
            <Form.Label>Time Spent (In Hrs)</Form.Label>
            <Form.Control onChange={(e)=>window.hours =e.target.value} type="number" />
        </Form.Group>
       </Form>

          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={handleClose}>
              Close
            </Button>
            <Button type="submit" variant="primary" onClick={()=>{

            
            if(window.reg!== null && window.hours  !== null  && window.yrs !== null && window.kms !== null &&  window.fmn !== null && window.unit !== null && window.reportingdate !== null){
              if(props.list.includes(window.reg) === true){
                setExists(true)
              }
              else{
                props.loadmodule(true)
      

              var data = JSON.stringify({"username":atob(localStorage.getItem('id')),
              "regno":window.reg,
              "type" : localStorage.getItem('vehicletype'),
              "hrs":window.hours ,
              "kms":window.kms,
              "yrs" : window.yrs,
              "fmn" : window.fmn,
              "unit" : window.unit,
              "reportingdate" : window.reportingdate,
              "target" : window.target,
              
              });
          
          var config = {
            method: 'post',
            url: 'http://localhost:8000/api/alltrucks',
            headers: { 
              'Content-Type': 'application/json'
            },
            data : data
          };

          axios(config)
          .then(function (response) {
            handleClose()
            setMiss(false)
            props.loadmodule(false)

          })
          .catch(function (error) {
            console.log(error);
          });
              }
          
            }else {
              setMiss(true)
              
            }
         
              
              }}>
            Submit 
            </Button>
          </Modal.Footer>
        </Modal>
      </>
    )
}




export default AddTruckModal;