import {Container,Table,Spinner} from 'react-bootstrap';
import {useState,useEffect} from 'react';
import axios from 'axios';




const UserDetails = (props)=>{

    const [data,setData] = useState(null)

    useEffect(()=>{
        var data = JSON.stringify({"username":props.id});

        var config = {
        method: 'post',
        url: 'http://localhost:8000/api/userdetails',
        headers: { 
            'Content-Type': 'application/json'
        },
        data : data
        };

        axios(config)
        .then(function (response) {
            setData(response.data)
        })
        .catch(function (error) {
        console.log(error);
        });


// eslint-disable-next-line
    },[])

    return (
        <>
        <Container>
           {data !== null ? (
               <>
               <Table striped bordered hover variant="dark">
  <tbody>

    <tr>
      <th>Name</th>
      <td>{data.name}</td>

    </tr>
    <tr>
      <th>Level</th>
      <td>{data.level}</td>
    
    </tr>
    <tr>
      <th>Rank</th>
      <td>{data.rank}</td>
    </tr>

    <tr>
      <th>Army Number</th>
      <td>{data.armynumber}</td>
    </tr>


    <tr>
      <th>Years of Exp</th>
      <td>{data.yearsofexp}</td>
    </tr>

    <tr>
      <th>Section</th>
      <td>{data.section}</td>
    </tr>

    <tr>
      <th>Techincal Qualification</th>
      <td>{data.techincalqualification}</td>
    </tr>
  </tbody>
</Table>
               </>
           ): (
               <>
               <Spinner animation="border" role="status">
                <span className="visually-hidden">Loading...</span>
                </Spinner>
               </>
           )}
       
          
        </Container>
        </>
    )
}
export default UserDetails;