import {useState,useEffect} from 'react';
import {Container, Form,Button,Nav} from 'react-bootstrap';
import axios from 'axios';
import UserDetails from '../components/UserDetails';
import UserActivityDetails from '../components/UserActivityDetails';
import UserMustDoChanges from '../components/UserMustDoChanges';
import UserCouldDoLife from '../components/UserCouldDoLife';
import UserCouldDoNoLife from '../components/UserCouldDoNoLife';
import UserRotableReport from '../components/UserRotablesReport';
import UserExpendablesReport from '../components/UserExpendablesReport';
import UserDelayReport from '../components/UserDelayReport';

let userIDs = []
let userNames = []
let userID = ""
let userName =""

const UserReport = ()=>{
    const [term,setSearchTerm] = useState("")
    const [tab,setTab] = useState(1)
    const [search,setSearch] = useState(false)

    useEffect(()=>{
        var config = {
            method: 'get',
            url: 'http://localhost:8000/api/userlist',
            headers: { 
              'Content-Type': 'application/json'
            },
          };
          
          axios(config)
          .then(function (response) {
            for(var i = 0; i < response.data.length ; i ++)
            {
              userNames.push(response.data[i].name)
            userIDs.push(response.data[i].username)
            }
     
              
        })
          .catch(function (error) {
            console.log(error);
          });
          

//eslint-disable-next-line
    },[])
 
  
   
      return (
        <>
                <Container className="bg-dark text-light my-5 py-3">  
        <h1 className="my-2 fw-bold">Search for User's Name</h1>
        

        <Form>
        <div className="row">
  <Form.Group className="col-sm-4" controlId="formBasicEmail">
    <Form.Label>User Names. (Start Typing to Search)</Form.Label>
    <Form.Label><p>Note: If you find your desired User, click on it to view its report</p></Form.Label>
    <Form.Control type="text" value={term} onChange={(e)=>setSearchTerm(e.target.value)} placeholder="Enter User ID : For Eg : temp1" />
  </Form.Group>
     </div>
        </Form>
       </Container>

       
       <Container className="bg-dark py-2 px-2">
        <div className="row my-3">
            {userNames.filter(
            (val,key)=>{
              if(term === "")
              return false;
              else if(val.toLowerCase().includes(term.toLowerCase()))
              return val;
              return false;
            }

        ).map((elem,index)=>{
          return (
            <div key={index} className="col">
            <Button onClick={()=>{
              setSearch(true)
              userName = elem
              for(var i = 0; i < userNames.length; i++ ){
                if(userNames[i] === elem){
                  userID = userIDs[i]
                  break
                }
              }
              setSearchTerm('')


            }} className="my-3 mx-3" variant="success">{elem} </Button>
            </div>
          )

        })}
     
       
        </div>
        </Container>

        
        {search === true?(
          <>
          <Container className="bg-dark text-light">
          <h1>Name : {userName} </h1>
          <Button
          className="mb-3 mx-auto"
          onClick={()=>{
            setSearchTerm('')
            setSearch(false)
          }}
          >Click here to search for a new User</Button>
          </Container>
          <Container
      className="my-5 bg-warning fw-bold text-dark"
      >
       <Nav variant="tabs" defaultActiveKey={1}>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
    className="text-dark" 
    onClick={()=>{
      setTab(1)
    }}
    eventKey={1}>User Report </Nav.Link>
  </Nav.Item>

  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
    className="text-dark" 
    onClick={()=>{
      setTab(2)
    }}
    eventKey={2}>Activity Report</Nav.Link>
  </Nav.Item>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(3)
  }}
       className="text-dark"  eventKey={3}>Must Do Changes Report</Nav.Link>
  </Nav.Item>
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(4)
  }}
       className="text-dark"  eventKey={4}>Could Do Changes Report(With Life)</Nav.Link>
  </Nav.Item>
 
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(5)
  }}
       className="text-dark"  eventKey={5}>Could Do Changes Report(Without Life)</Nav.Link>
  </Nav.Item>


  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(6)
  }}
    className="text-dark"  eventKey={6}>Rotables Report</Nav.Link>
  </Nav.Item>

  
  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(7)
  }}
    className="text-dark"  eventKey={7}>Expendables Report</Nav.Link>
  </Nav.Item>


  <Nav.Item className="border border-2 border-dark">
    <Nav.Link
     onClick={()=>{
    setTab(8)
  }}
    className="text-dark"  eventKey={8}>Delay Table Report</Nav.Link>
  </Nav.Item>




  

</Nav>
</Container>
{tab === 1?<UserDetails id={userID} name={userName} />: null}
{tab === 2?<UserActivityDetails id={userID} name={userName}/> : null}
{tab === 3?<UserMustDoChanges id={userID} name={userName}/> : null}
{tab === 4?<UserCouldDoLife id={userID} name={userName}/> : null}
{tab === 5?<UserCouldDoNoLife id={userID} name={userName}/>: null}
{tab === 6?<UserRotableReport id={userID} name={userName}/>: null}
{tab === 7?<UserExpendablesReport id={userID} name={userName}/> : null}
{tab === 8?<UserDelayReport id={userID} name={userName}/> : null }
          </>
        ):null}
 
      
        </>
      )
  
}

export default UserReport;