import {Container,Table,Spinner,Button} from 'react-bootstrap';
import {useEffect,useState} from 'react';
import axios from 'axios';
import jsPDF from 'jspdf'; 
import 'jspdf-autotable';


function convertDate(inputFormat) {
  function pad(s) { return (s < 10) ? '0' + s : s; }
  var d = new Date(inputFormat)
  return [pad(d.getDate()), pad(d.getMonth()+1), d.getFullYear()].join('/')
}

function generate(temp,user) {  

  const unit = "pt";
  const size = "A4"; // Use A1, A2, A3 or A4
  const orientation = "portrait"; // portrait or landscape

  const marginLeft = 40;
  const doc = new jsPDF(orientation, unit, size);
  doc.setFont(undefined, 'bold')

  doc.setFontSize(15);

  const title = `Life Item Report for user : ${user}`;
  const headers = [["S No.", "Tank BA No.","Item","Lifting Norms","Fitted (Yes/No)","Remarks","TimeStamp"]];

  const data = temp.map((elem,index)=> {
    let remarks = "",fitted = ""
    try{remarks = elem.info.split('remarks:')[1].split('for')[0].trim()}catch(e){}
    try{fitted=elem.info.split('fitted: ')[1].split(RegExp(',|for'))[0]}catch(e){}
    if(remarks === "None") remarks = ""
    let liftingnorms = ""
    if(elem.hrs !== null) liftingnorms += `${elem.hrs} hrs, `
    if(elem.kms !== null) liftingnorms += `${elem.kms} kms, `
    if(elem.cycles !== null) liftingnorms += `${elem.cycles} cycles, `
    if(elem.efcs !== null)  liftingnorms += `${elem.efcs} efcs, `
    if(elem.operations !== null) liftingnorms += `${elem.operations} operations, `
    if(elem.switchings !== null) liftingnorms += `${elem.switchings} switchings, `
    if(elem.yrs !== null) liftingnorms += `${elem.yrs} yrs, ` 
    return [index+1, elem.truck,elem.item,liftingnorms,fitted,remarks,
      
      convertDate(elem.timestamp.split(',')[0])]
  
  });

  let content = {
    startY: 50,
    head: headers,
    body: data,
    theme : "grid",
    styles : {
      halign : "left",
    },
    bodyStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center',
    },
    headStyles: {
      lineWidth: 1,
      lineColor: 10,
      valign: "middle",
      halign: 'center'
    },
  };

  doc.text(title, marginLeft, 40);
  doc.autoTable(content);
  doc.save("report.pdf")
}  


const UserCouldDoLife = (props)=>{


    const [data,setData] = useState(null)

    useEffect(()=>{

        var data = JSON.stringify({"username":props.id,
      "type" : localStorage.getItem('vehicletype')});

        var config = {
          method: 'post',
          url: 'http://localhost:8000/api/trucktimeitemhistory',
          headers: { 
            'Content-Type': 'application/json'
          },
          data : data
        };
        
        axios(config)
        .then(function (response) {
            setData(response.data)
        })
        .catch(function (error) {
          console.log(error);
        });
        
        // eslint-disable-next-line
    },[])


    return (
        <>
        <Container>
        {data !== null? (
            <>
            <Table striped bordered hover variant="dark">
  <thead>
    <tr>
      <th>S No. </th>
      <th>Tank BA No.</th>
      <th>Username</th>
      <th>Item</th>
      <th>Lifting Norms</th>
      <th>Fitted (Yes/No)</th>
      <th>Remarks</th>
      <th>Time Stamp</th>
    </tr>
  </thead>
  <tbody>
  {data.map((elem,index)=>{
    let remarks = "",fitted = ""
    try{remarks = elem.info.split('remarks:')[1].split('for')[0].trim()}catch(e){}
    try{fitted=elem.info.split('fitted: ')[1].split(RegExp(',|for'))[0]}catch(e){}
    if(remarks === "None") remarks = ""  
    let liftingnorms = ""
    if(elem.hrs !== null) liftingnorms += `${elem.hrs} hrs, `
    if(elem.kms !== null) liftingnorms += `${elem.kms} kms, `
    if(elem.cycles !== null) liftingnorms += `${elem.cycles} cycles, `
    if(elem.efcs !== null)  liftingnorms += `${elem.efcs} efcs, `
    if(elem.operations !== null) liftingnorms += `${elem.operations} operations, `
    if(elem.switchings !== null) liftingnorms += `${elem.switchings} switchings, `
    if(elem.yrs !== null) liftingnorms += `${elem.yrs} yrs, ` 
    
    return (
        <tr>
      <td>{index + 1}</td>
      <td>{elem.truck}</td>
      <th>{props.name}</th>
      <td>{elem.item}</td>
      <td>{liftingnorms}</td>
      <td>{fitted}</td>
      <td>{remarks}</td>
      <td>{convertDate(elem.timestamp.split(',')[0])}</td>
    </tr>
      )
  })}
    
    
  </tbody>
</Table>
            </>
        ): (
            <>
            <Spinner animation="border" role="status">
                <span className="visually-hidden">Loading...</span>
                </Spinner>
               </>
        )}
       
        <Button variant="success" onClick={()=>{
            generate(data,props.name)
          }}>Generate Report</Button>
        </Container>
        </>
    )
}

export default UserCouldDoLife;