// import {Container, Button, Table,Form,Spinner} from 'react-bootstrap';
import { useLocation, useHistory} from 'react-router';
import MustDoInventory from '../components/MustDoInventory';
import CouldDoInventory from '../components/CouldDoInventory';
import { Nav, Container, Button } from 'react-bootstrap';
import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import ExpendableItems from '../components/ExpendableItems';

const AllInventoryItems = () => {
  
  const [tab, setTab] = useState(1)
  
  useEffect(() => {
    
    if (localStorage.getItem('inventory') === null) {
      localStorage.setItem('inventory', 'must')
    }
    if (localStorage.getItem('inventory') === 'could')
    setTab(2)
    else if(localStorage.getItem('inventory') === 'expendable')
    setTab(3)
    else
    setTab(1)
  }, [])
  const location = useLocation();
  const history = useHistory();
  return (
    <>
      {location.state !== undefined && localStorage.getItem('id') !== null ? (
        <>
        <Container className="text-dark" style={{
          "backgroundColor" : "#2a6099",
          "textAlign":'center'
        }}>
          <h1 className="my-2 mx-5 fw-bold">{localStorage.getItem('vehicletype') === "BMP"?"BMP-II":(localStorage.getItem('vehicletype') === "T72"?"T-72" : "T-90")} SECTION</h1>
        </Container>
          <Container className="bg-warning fw-bold">

            <h3 className="fw-bold my-2">Tank BA Number : {location.state}</h3>

            <hr style={{
              height: '3px',
            }} />
            <Nav variant="tabs" activeKey={tab}>

            <Button id="btnclose" onClick={()=>{
            history.push('/maintruckdb')
            window.location.reload()
            }} style={{margin:'5px'}} variant="success">Go Back
            </Button>

              <Nav.Item className="border border-2 border-dark">
                <Nav.Link
                  className="text-dark"
                  onClick={() => {
                    setTab(1)
                    localStorage.setItem('inventory', 'must')
                  }}
                  eventKey={1}>Must Do Inventory </Nav.Link>
              </Nav.Item>
              <Nav.Item
                className="border border-2 border-dark"
              >
                <Nav.Link
                  onClick={() => {
                    setTab(2)
                    localStorage.setItem('inventory', 'could')

                  }}
                  className="text-dark" eventKey={2}>Could Do Inventory</Nav.Link>
              </Nav.Item>

              <Nav.Item
                className="border border-2 border-dark"
              >
                <Nav.Link
                  onClick={() => {
                    setTab(3)
                    localStorage.setItem('inventory', 'expendable')

                  }}
                  className="text-dark" eventKey={3}>Expendable Items</Nav.Link>
              </Nav.Item>

            </Nav>
          </Container>
                {tab === 1?<MustDoInventory reg={location.state}/> : null}
                {tab === 2?<CouldDoInventory reg={location.state}/> : null}
                {tab === 3?<ExpendableItems reg={location.state}/> : null} 
        </>
      ) : (
        <>
          <h1 className="mx-2 my-3 text-center fw-bold"> It seems You Are Lost !! Click Here to Go Back!!
            <br />
            <Link to="/maintruckdb" ><Button size="lg" variant="success">Home Page</Button></Link>
          </h1>
        </>
      )}


    </>
  )
}

export default AllInventoryItems;